return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Polish','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-10 14:38+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'pl_PL','plural-forms'=>'nplurals=3; plural=(n==1 ? 0 : n%10 >= 2 && n%10<=4 &&(n%100<10||n%100 >= 20)? 1 : 2);','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" zapisano.','"%1$s" created. %2$d template updated.'=>'"%1$s" został utworzony. %2$d szablonów zaktualizowanych.' . "\0" . '"%1$s" został utworzony. %2$d szablonów zaktualizowanych.' . "\0" . '','"%s" created.'=>'"%s" został utworzony.','"product" (replaces "article")'=>'"produkt" (zastępuje "artykuł")','"Treat H2 as H1 equivalent" (Settings → SEO → Analysis): enable this when your theme renders the post title inside an H2 instead of an H1. The analyser promotes the first H2 to H1 so the score is not incorrectly penalised.'=>'"Traktuj H2 jako równoważne H1" (Ustawienia → SEO → Analiza): włącz to, gdy Twój motyw renderuje tytuł posta wewnątrz H2 zamiast H1. Analizator promuje pierwszy H2 do H1, aby wynik nie był nieprawidłowo penalizowany.','%1$d chars — good, slightly above the ideal %2$d but within the accepted %3$d-char range. %4$s'=>'%1$d znaków — dobry wynik, nieco powyżej idealnej wartości %2$d, ale w ramach akceptowalnego zakresu %3$d znaków. %4$s','%1$d chars — ideal length. %2$s'=>'%1$d znaków — idealna długość. %2$s','%1$d chars — likely truncated in SERPs (keep under %2$d). %3$s'=>'%1$d znaków — prawdopodobnie obcięte w wynikach wyszukiwania (zachowaj poniżej %2$d). %3$s','%1$d chars — too short (aim for %2$d–%3$d). %4$s'=>'%1$d znaków — za krótko (dąż do %2$d–%3$d). %4$s','%1$d chars, %2$d words — good title.'=>'%1$d znaków, %2$d słów — dobry tytuł.','%1$d internal, %2$d external.'=>'%1$d wewnętrznych, %2$d zewnętrznych.','%1$d of %2$d image(s) missing alt text.'=>'Brakujący tekst alternatywny dla %1$d z %2$d obrazów.','%1$d post tagged with _lf_lang = %2$s.'=>'%1$d opublikowanych wpisów oznaczonych _lf_lang = %2$s.' . "\0" . '%1$d opublikowanych wpisów oznaczonych _lf_lang = %2$s.' . "\0" . '','%1$d words — below recommended minimum of %2$d.'=>'%1$d słów — poniżej zalecanego minimum %2$d.','%1$d words — very thin content. Consider expanding to at least %2$d words.'=>'%1$d słów — bardzo mała zawartość. Rozważ rozszerzenie do co najmniej %2$d słów.','%d external link(s), no internal links.'=>'%d zewnętrznych linków, brak linków wewnętrznych.','%d external link(s), no internal links. Add internal links to related content.'=>'%d zewnętrznych linków, brak wewnętrznych. Dodaj linki wewnętrzne do powiązanej treści.','%d H1 tags found — a page should have exactly one H1.'=>'Znaleziono %d tagów H1 — strona powinna mieć dokładnie jeden H1.','%d image(s), all have alt text.'=>'%d obrazów, wszystkie mają tekst alternatywny.','%d language not yet linked'=>'%d język jeszcze nie powiązany' . "\0" . '%d języków jeszcze nie powiązanych' . "\0" . '','%d link updated.'=>'%d link zaktualizowany.' . "\0" . '%d linków zaktualizowanych.' . "\0" . '','%d locale file could not be removed automatically (DISALLOW_FILE_MODS is set). Delete it manually via your server or WP-CLI: wp language core uninstall <locale>'=>'Nie można automatycznie usunąć pliku lokalizacji %d (DISALLOW_FILE_MODS jest ustawione). Usuń go ręcznie na serwerze lub za pomocą WP-CLI: wp language core uninstall <locale>.' . "\0" . 'Nie można automatycznie usunąć plików lokalizacji %d (DISALLOW_FILE_MODS jest ustawione). Usuń je ręcznie na serwerze lub za pomocą WP-CLI: wp language core uninstall <locale>.' . "\0" . '','%d locale file removed.'=>'Usunięto plik lokalizacji %d.' . "\0" . 'Usunięto pliki lokalizacji: %d.' . "\0" . '','%d locale pack installed.'=>'Zainstalowano %d pakiet lokalizacyjny.' . "\0" . 'Zainstalowano %d pakietów lokalizacyjnych.' . "\0" . '','%d navigation reference updated.'=>'%d odwołanie do nawigacji zaktualizowane.' . "\0" . '%d odwołań do nawigacji zaktualizowanych.' . "\0" . '','%d part reference updated.'=>'%d odwołanie do części zaktualizowane.' . "\0" . '%d odwołań do części zaktualizowanych.' . "\0" . '','%d post'=>'%d wpis' . "\0" . '%d wpisów' . "\0" . '','%d rule registered'=>'Zarejestrowano %d regułę' . "\0" . 'Zarejestrowano %d reguły' . "\0" . '','%d words.'=>'%d słów.','%s Archive'=>'%s Archiwum','%s is active and already outputs Schema.org JSON-LD. Lingua Forge has disabled its own schema output to prevent conflicting graphs. Unlike Open Graph — where LF adds og:locale on top of another plugin\'s output — schema cannot be cleanly supplemented: duplicate or overlapping JSON-LD graphs produce validation errors. Disable schema output in the detected plugin if you want LF to handle structured data.'=>'%s jest aktywne i już generuje Schema.org JSON-LD. Lingua Forge wyłączyło własne wyjście schematu, aby zapobiec konfliktom grafów. W przeciwieństwie do Open Graph — gdzie LF dodaje og:locale na podstawie innej wtyczki — schemat nie może być czysto uzupełniony: duplikaty lub nakładające się grafy JSON-LD powodują błędy walidacji. Wyłącz wyjście schematu w wykrytej wtyczce, jeśli chcesz, aby LF obsługiwał dane strukturalne.','%s is active and generates its own sitemap. That sitemap is separate from LF\'s. Both should be submitted to Google Search Console: the SEO plugin sitemap lists your content; the LF sitemap adds the multilingual alternate links. LF\'s sitemap is announced in robots.txt automatically.'=>'%s jest aktywne i generuje własną mapę witryny. Ta mapa jest oddzielna od mapy LF. Obie powinny być zgłoszone do Google Search Console: mapa witryny SEO wymienia Twoje treści; mapa LF dodaje wielojęzyczne linki alternatywne. Mapa LF jest automatycznie zgłaszana w robots.txt.','(active)'=>'(aktywny)','(avg %.1f hits/block)'=>'(średnio %.1f trafień/blok)','(avg %.1f hits/entry)'=>'(średnio %.1f trafień/pozycję)','(classic theme)'=>'(klasyczny motyw)','(disabled)'=>'wyłączone','(FSE / block theme)'=>'(FSE / motyw blokowy)','(no title) #%d'=>'(brak tytułu) #%d','(partial)'=>'(częściowy)','(server/FPM timeout still applies)'=>'(wciąż obowiązuje limit czasu serwera/FPM)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} nie miało wymienialnych linków — ponowne skanowanie w celu sprawdzenia)','.txt file(s) in the directory'=>'.txt plik(i) w katalogu','/ 100'=>'/ 100','1 H1 ✓ — no H2 or H3 subheadings found. Adding H2s improves structure.'=>'1 H1 ✓ — nie znaleziono nagłówków H2 ani H3. Dodanie H2 poprawia strukturę.','1 H1 ✓ — no H2 subheadings (acceptable for this content type).'=>'1 H1 ✓ — brak podtytułów H2 (akceptowalne dla tego typu treści).','1 H1 ✓ — no H2, but %d H3 subheading(s) found (e.g. accordion/details headers). Structure is acceptable.'=>'1 H1 ✓ — brak H2, ale znaleziono %d podtytuł(i) H3 (np. nagłówki akordeonów/szczegółów). Struktura jest akceptowalna.','1 H1 ✓ — short content (%d paragraph(s)), subheadings not required.'=>'1 H1 ✓ — krótka treść (%d akapitów), podtytuły nie są wymagane.','1 H1 ✓, %1$d H2, %2$d H3.'=>'1 H1 ✓, %1$d H2, %2$d H3.','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d lokalizowanych szablonów z motywu „%2$s” jest zachowanych w bazie danych, ale są obecnie nieaktywne. Ponownie staną się aktywne, jeśli ponownie aktywujesz ten motyw. Aby przenieść swoje tłumaczenia do nowego motywu, wygeneruj je ponownie za pomocą <strong>Ustawienia → Lingua Forge → Router → FSE scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> automatycznie naprawialnych linków','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> linków wymagających ręcznej weryfikacji','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> nieaktualna(e) ścieżka(e)','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> problem(y) z szablonem','_lf_lang Coverage'=>'Pokrycie _lf_lang','A physical robots.txt file exists at the site root. WordPress\'s virtual robots.txt — and LF\'s Sitemap: filter — are bypassed. The LF sitemap is not announced to search engines.'=>'Na stronie istnieje fizyczny plik robots.txt. Wirtualny robots.txt WordPressa — i filtr Sitemap LF — są pomijane. Mapa witryny LF nie jest zgłaszana wyszukiwarkom.','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Akceptuje tylko skompilowane pliki .mo. Nazwa pliku musi mieć wzór {textdomain}-{locale}.mo. Przesłanie pliku o tej samej nazwie co istniejący spowoduje jego zastąpienie.','Access forbidden — your account may be suspended or the key lacks the required permissions.'=>'Dostęp zabroniony — Twoje konto może być zawieszone lub klucz nie ma wymaganych uprawnień.','Action'=>'Akcja','active'=>'aktywne','Active Languages'=>'Aktywne języki','Active languages'=>'Aktywne języki','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Aktywne języki: dodaj każdy język, który chcesz obsługiwać. Każdy język otrzymuje prefiks URL lub subdomenę oraz tag hreflang w sekcji &lt;head&gt; strony.','Active Plugins'=>'Aktywne wtyczki','Active preset'=>'Aktywny preset','Active Provider'=>'Aktywny dostawca','Active theme'=>'Aktywny motyw','Active: %s.'=>'Aktywny: %s.','Add entry'=>'Dodaj wpis','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Dodaj instrukcje, aby ulepszyć szkic — np. skróć go, dodaj sekcję podsumowania, użyj bardziej formalnego rejestru, dodaj blok FAQ…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Dodaj instrukcje, aby poprawić szkic — np. skróć go, dodaj sekcję podsumowania, użyj bardziej formalnego rejestru…','Add key →'=>'Dodaj klucz →','Add new entry'=>'Dodaj nowy wpis','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Dodaj jeden termin na wiersz. Zarówno termin źródłowy, jak i docelowy są wymagane. Para języków określa, do których zadań tłumaczeniowych obowiązuje ograniczenie.','Add Sitemap directive to robots.txt'=>'Dodaj dyrektywę Sitemap do robots.txt','Add the following line to your robots.txt manually:'=>'Dodaj następującą linię do robots.txt ręcznie:','Add WooCommerce product tags to Open Graph output'=>'Dodaj tagi produktów WooCommerce do wyjścia Open Graph','Adds a link to the home page so visitors can browse in their language.'=>'Dodaje link do strony głównej, aby odwiedzający mogli przeglądać w swoim języku.','Administrators only (manage_options)'=>'Tylko administratorzy (zarządzaj_opcjami)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Po zmianie głównego języka, odśwież permalink (sekcja poniżej), aby zaktualizować trasowanie URL.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Po zmianie ustawień struktury URL (prefiks ścieżki ↔ subdomena), zawsze odwiedź Ustawienia → Bezpośrednie odnośniki i kliknij Zapisz zmiany, aby odświeżyć reguły przekierowań.','AI analysis failed. Please try again.'=>'Analiza AI nie powiodła się. Spróbuj ponownie.','AI Behaviour Preset'=>'Predefiniowany zachowanie AI','AI cache cleared. %d entry was removed.'=>'Pamięć podręczna AI wyczyszczona. %d wpis został usunięty.' . "\0" . 'Pamięć podręczna AI wyczyszczona. %d wpisów zostało usuniętych.' . "\0" . '','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'Pamięć podręczna AI: lista zapisanych odpowiedzi AI z licznikami trafień. Wyczyść całą pamięć podręczną lub wpisy pojedynczego posta. Użyj "Wyczyść" przed testowaniem zmiany tłumaczenia — zapisane wyniki są zwracane nawet po zmianie presetów lub modelu AI, dopóki wpis w pamięci podręcznej nie zostanie usunięty.','AI Configuration'=>'Konfiguracja AI','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Funkcje AI są opcjonalne. Routing językowy, hreflang, przełącznik języków i system grup tłumaczeń działają bez skonfigurowanego dostawcy.','AI Limits & Security'=>'Limity i bezpieczeństwo AI','AI Provider'=>'Dostawca AI','AI provider returned an empty response.'=>'Dostawca AI zwrócił pustą odpowiedź.','AI Recommendations'=>'Rekomendacje AI','AI returned an unexpected response format. Please try again.'=>'AI zwróciło nieoczekiwany format odpowiedzi. Spróbuj ponownie.','AI translation and batch analysis may time out. Recommend 120s or more.'=>'Tłumaczenie AI i analiza wsadowa mogą się wyłączyć. Zalecane 120 sekund lub więcej.','AI Usage'=>'Użycie AI','AI Usage & Cache'=>'Użycie AI i pamięć podręczna','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Celuj w 120–160 znaków. Pozostaw puste, aby użyć zapasowego fragmentu.','All major search engines — Google, Bing, and Yandex — discover the sitemap automatically via the Sitemap: directive in robots.txt. No manual action is required. The buttons below send an immediate ping so the engine recrawls the sitemap now rather than waiting for its next scheduled robots.txt check.'=>'Wszystkie główne wyszukiwarki — Google, Bing i Yandex — automatycznie wykrywają mapę witryny za pomocą dyrektywy Sitemap w robots.txt. Nie jest wymagana ręczna interwencja. Przyciski poniżej wysyłają natychmiastowe odwołanie, aby wyszukiwarka ponownie pobrała mapę witryny teraz, a nie czekała na kolejną zaplanowaną kontrolę robots.txt.','All published posts have a _lf_lang value. No gaps detected.'=>'Wszystkie opublikowane wpisy mają wartość _lf_lang. Nie wykryto luk.','All time'=>'Wszystko','All types'=>'Wszystkie typy','Allow editors to lock individual blocks'=>'Zezwól redaktorom na blokowanie poszczególnych bloków','Allow Gutenberg template-editing mode on post screens'=>'Zezwól na tryb edycji szablonów Gutenberga na ekranach wpisów','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Usuń również przypisania językowe, relacje tłumaczeń, meta opisy, glosariusz i pamięć tłumaczeń podczas odinstalowania wtyczki.','Also generate meta description'=>'Również wygeneruj metaopis','Alternative (server-side):'=>'Alternatywnie (po stronie serwera):','Always emit only og:locale and og:locale:alternate. Use when another plugin or theme handles the full OG set.'=>'Zawsze emituj tylko og:locale i og:locale:alternate. Używaj, gdy inna wtyczka lub motyw obsługuje pełny zestaw OG.','Always emit the complete OG + Twitter Card set regardless of other plugins. Use only if no other plugin outputs OG tags.'=>'Zawsze emituj pełny zestaw OG + Twitter Card, niezależnie od innych wtyczek. Używaj tylko, jeśli żadna inna wtyczka nie generuje tagów OG.','An unknown error occurred.'=>'Wystąpił nieznany błąd.','Analyse'=>'Analiza','Analyse all languages'=>'Analiza wszystkich języków','Analyse…'=>'Analiza…','Analysis'=>'Analiza','Analysis request failed. Please try again.'=>'Żądanie analizy nie powiodło się. Spróbuj ponownie.','Analyzing…'=>'Analiza…','and'=>'i','Anthropic (Claude)'=>'Anthropic (Claude)','Anthropic Console'=>'Konsola Anthropic','any'=>'dowolny','API calls saved by cache'=>'Wywołania API zapisane w pamięci podręcznej','API Key'=>'Klucz API','API Keys'=>'Klucze API','API Keys Tab'=>'Zakładka kluczy API','API Response Cache'=>'Pamięć podręczna odpowiedzi API','API Response Cache setting saved.'=>'Ustawienie pamięci podręcznej odpowiedzi API zapisane.','Appends the following line to your existing robots.txt: %s'=>'Dodaje następującą linię do istniejącego robots.txt: %s','Applied ✓'=>'Zastosowano ✓','Apply failed — please try again.'=>'Nie udało się zastosować — spróbuj ponownie.','Apply to all language versions'=>'Zastosuj do wszystkich wersji językowych','Apply to Block'=>'Zastosuj do bloku','Apply to Editor'=>'Zastosuj do Edytora','Apply to Footnote'=>'Zastosuj do przypisu','Apply to Meta Description'=>'Zastosuj do Opisu Meta','Apply translation'=>'Zastosuj tłumaczenie','Applying…'=>'Zastosowanie…','Approximate size'=>'Przybliżony rozmiar','Archive'=>'Archiwum','Archive: %s'=>'Archiwum: %s','Article / WebPage'=>'Artykuł / Strona internetowa','Article / WebPage — all singular posts and pages'=>'Artykuł / Strona internetowa — wszystkie pojedyncze posty i strony','Authors and above (edit_published_posts)'=>'Autorzy i wyżej (edytuj_opublikowane_posty)','Auto (recommended)'=>'Auto (zalecane)','Auto-detect assigns: WooCommerce products → Product profile; the static front page → Landing profile; everything else → Blog profile. Choose a specific profile to override this for all posts.'=>'Automatyczne wykrywanie przypisuje: produkty WooCommerce → profil produktu; statyczna strona główna → profil landing; wszystko inne → profil bloga. Wybierz konkretny profil, aby to nadpisać dla wszystkich wpisów.','Auto-detected for the static front page; can be selected manually. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 10 pts · Images 15 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 150, fails below 60; H2 and internal links optional.'=>'Automatycznie wykryte dla statycznej strony głównej; można wybrać ręcznie. Tytuł 20 pkt · Meta opis 30 pkt · Liczba słów 15 pkt · Nagłówki 10 pkt · Obrazy 15 pkt · Linki 0 pkt. Limit tytułu w SERP 70 znaków; ostrzeżenie przy poniżej 150 słów, niepowodzenie poniżej 60; H2 i wewnętrzne linki opcjonalne.','Auto-detected for WooCommerce products. Title 20 pts · Meta description 30 pts · Word count 15 pts · Headings 5 pts · Images 20 pts · Links 0 pts. Title SERP limit 70 chars; word count warns below 80, fails below 40; H2 and internal links optional.'=>'Automatycznie wykryte dla produktów WooCommerce. Tytuł 20 pkt · Meta opis 30 pkt · Liczba słów 15 pkt · Nagłówki 5 pkt · Obrazy 20 pkt · Linki 0 pkt. Limit tytułu w SERP 70 znaków; ostrzeżenie przy poniżej 80 słów, niepowodzenie poniżej 40; H2 i wewnętrzne linki opcjonalne.','Available models reference'=>'Odwołanie do dostępnych modeli','avg'=>'średnia','Batch Analysis'=>'Analiza wsadowa','Behavior'=>'Zachowanie','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Zachowanie: wybierz preset AI (Literal, Balanced, Creative), dodaj instrukcje niestandardowe dla całej witryny, włącz lub wyłącz automatyczne tłumaczenie po zapisaniu posta oraz skonfiguruj Pamięć tłumaczeń.','Block Content'=>'Zawartość bloku','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Wyświetla uprzejme powiadomienie, gdy obecna strona jest wyświetlana w jej języku źródłowym, ponieważ nie istnieje tłumaczenie dla języka odwiedzającego. Napędzane sygnałem LINGUAFORGE_LANG_FALLBACK_ACTIVE routera Lingua Forge — nie emituje nic, gdy istnieje tłumaczenie dla żądanej lokalizacji.','Block Editor'=>'Edytor bloków','block keywordfallback'=>'zapas','block keywordi18n'=>'i18n','block keywordlanguage'=>'język','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'tłumaczenie','Block locking'=>'Blokada','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Wzory bloków zarejestrowane dla niestandardowych typów postów. Użyj przycisku Tłumacz, aby wygenerować wersję językową. Tłumaczona zawartość jest zapisywana tutaj i może być skopiowana do dowolnego posta CPT z edytora bloków lub użyta jako punkt wyjścia dla Wzoru synchronizowanego (Blok wielokrotnego użytku).','block titleMissing Translation Notice'=>'Powiadomienie o braku tłumaczenia','Block translation reuses'=>'Ponowne użycie tłumaczeń bloków','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Glossary edits and Compliance preset changes automatically invalidate affected cached translations.'=>'Pamięć podręczna tłumaczeń na poziomie bloków współdzielona między wpisami. Gdy włączona, identyczne bloki (ta sama składnia, para języków i glosariusz) są serwowane z pamięci zamiast ponownego wywołania AI. Edycje glosariusza i zmiany presetów zgodności automatycznie unieważniają odpowiednie zapisane tłumaczenia.','Blog / Editorial'=>'Blog / Redakcja','Blog / Editorial (default)'=>'Blog / Redakcja (domyślnie)','Blog posts use Article; all other post types and pages use WebPage. Includes headline, description, inLanguage, url, datePublished, dateModified, image, and publisher.'=>'Posty na blogu używają Article; wszystkie inne typy postów i strony używają WebPage. Zawiera nagłówek, opis, inLanguage, url, datePublished, dateModified, obraz i wydawcę.','Browser language redirect'=>'Przekierowanie języka przeglądarki','Built-in preset instructions:'=>'Wbudowane instrukcje presetów:','Bulletize (•-prefixed)'=>'Użyj punktów (•-prefiks)','cached'=>'pamięć podręczna','Cached API responses'=>'Zapisane odpowiedzi API','Cached block translations'=>'Zapisane tłumaczenia bloków','Cancel'=>'Anuluj','Cannot determine target language from slug.'=>'Nie można określić docelowego języka na podstawie slug.','Cannot write to product %1$d: it is a translated version (language: %2$s)%3$s. Operational data (price, stock, SKU, dimensions) must be updated on the source product. Resolve the source product ID via: GET /wp-json/lingua-forge/v1/post/%4$d/translations'=>'Nie można zapisać produktu %1$d: jest to wersja tłumaczona (język: %2$s)%3$s. Dane operacyjne (cena, stan magazynowy, SKU, wymiary) muszą być aktualizowane na produkcie źródłowym. Rozwiąż ID produktu źródłowego za pomocą: GET /wp-json/lingua-forge/v1/post/%4$d/translations','Canonical tag'=>'Tag kanoniczny','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Ogranicz ilość korzystania z AI na stronie i ogranicz role użytkowników, które mogą wywołać płatne wywołania AI. Nakłada się na limit na poziomie użytkownika (30 żądań / minuta, na stałe), który już chroni przed niekontrolowanymi pętlami pojedynczego użytkownika.','Cart'=>'Koszyk','chars'=>'znaki','Check your account, billing, or remaining credits directly on the provider console:'=>'Sprawdź swoje konto, rozliczenia lub pozostałe kredyty bezpośrednio w konsoli dostawcy:','Checkout'=>'Kasa','Chunk translated'=>'Fragment przetłumaczony','Chunk translated to:'=>'Fragment przetłumaczony na:','Clear'=>'Wyczyść','Clear All'=>'Wyczyść wszystko','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Czy wyczyścić wszystkie zapisane wyniki AI? Przyszłe żądania będą wywoływać nowe wywołania API, aż do odbudowania pamięci podręcznej.','Clear API Response Cache'=>'Wyczyść pamięć podręczną odpowiedzi API','Clear Debug Files'=>'Wyczyść pliki debugowania','Clear hints'=>'Wyczyść podpowiedzi','Clear input'=>'Wyczyść wejście','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Wyczyścić całą pamięć tłumaczeń? Przyszłe tłumaczenia odbudują pamięć podręczną podczas ich wykonywania.','Clear Translation Memory'=>'Wyczyść pamięć tłumaczeń','Close'=>'Zamknij','Close language panel'=>'Zamknij panel językowy','Close popover'=>'Zamknij podpowiedź','Compatibility'=>'Zgodność','Compliance Preset'=>'Predefiniowany ustawienie zgodności','Configure an AI provider in Settings → API Keys to enable AI-powered recommendations.'=>'Skonfiguruj dostawcę AI w Ustawienia → Klucze API, aby włączyć rekomendacje oparte na AI.','Configure hreflang, Open Graph, Schema.org, sitemaps, and social sharing for every language on your site. Each section below handles one aspect of multilingual SEO.'=>'Konfiguruj hreflang, Open Graph, Schema.org, mapy witryn i udostępnianie społecznościowe dla każdego języka na Twojej stronie. Każda sekcja poniżej obsługuje jeden aspekt wielojęzycznego SEO.','Configured'=>'Skonfigurowano','Contact Form 7 (wpcf7_contact_form) is excluded automatically. Add any other third-party post types whose content should not be language-filtered, one per line or comma-separated.'=>'Formularz kontaktowy 7 (wpcf7_contact_form) jest automatycznie wykluczony. Dodaj inne typy postów stron trzecich, których treść nie powinna być filtrowana językowo, po jednej na linii lub oddzielone przecinkami.','Content generated'=>'Treść wygenerowana','Content Generator'=>'Generator treści','Content profiles and weights'=>'Profile treści i wagi','Content ready'=>'Treść gotowa','Contributors and above — default (edit_posts)'=>'Współtwórcy i wyżej — domyślnie (edytuj_posty)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Kontroluj, ile treści jest wysyłanych do AI i jak duża może być odpowiedź. Pozostaw puste, aby użyć wbudowanego domyślnego (pokazanego jako placeholder). Zwiększ te wartości, jeśli duże strony są obcinane; zmniejsz je, aby obniżyć koszty API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Kontroluje budżet tokenów i limity wejścia dla funkcji Generatora treści AI. Pozostaw puste, aby użyć wbudowanych domyślnych ustawień.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Kontroluje, co się dzieje, gdy administrator usuwa wtyczkę z Plugins → Installed Plugins → Delete. Ustawienia wtyczki i pamięć podręczna AI są zawsze usuwane. Przydziały językowe i relacje tłumaczeń są domyślnie zachowywane, więc przypadkowe odinstalowanie lub reinstalacja mogą kontynuować tam, gdzie zostały przerwane.','Conversational'=>'Konwersacyjne','Copied ✓'=>'Skopiowano ✓','Copied!'=>'Skopiowano!','Copy'=>'Kopiuj','Copy and paste into a GitHub issue or support request.'=>'Skopiuj i wklej do zgłoszenia na GitHub lub prośby o wsparcie.','Copy failed — please copy the URL manually.'=>'Nie udało się skopiować — skopiuj URL ręcznie.','Copy markup'=>'Kopiuj kod','Copy system info'=>'Skopiuj informacje o systemie','Copy the current URL to the clipboard. Shows a "Link copied" toast on success.'=>'Skopiuj bieżący URL do schowka. Pokaże się powiadomienie "Link skopiowany" po sukcesie.','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Skopiuj wynik i wklej tam, gdzie jest to potrzebne (np. bezpośrednio do pola przypisu).','Copy to safe storage'=>'Kopiuj do bezpiecznej pamięci','copy/native/auto JS actions: handled by LF\'s social-share.js'=>'akcje JS kopiowania/natywne/auto: obsługiwane przez social-share.js LF','Could not add entry: source term and target term are required.'=>'Nie można dodać wpisu: wymagany jest termin źródłowy i termin docelowy.','Could not copy the file. Check that the uploads folder is writable.'=>'Nie można skopiować pliku. Sprawdź, czy folder uploads jest zapisywalny.','Could not instantiate the provider.'=>'Nie można utworzyć instancji dostawcy.','Could not save the file. Check that the uploads folder is writable.'=>'Nie można zapisać pliku. Sprawdź, czy folder uploads jest zapisywalny.','Could not save the glossary entry.'=>'Nie można zapisać wpisu słownika.','Could not write to robots.txt. Check file permissions.'=>'Nie można zapisać do robots.txt. Sprawdź uprawnienia pliku.','CPT Block Patterns'=>'Wzory bloków CPT','Create'=>'Utwórz','Create missing'=>'Utwórz brakujące','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Tworzenie tłumaczeń dla typu posta "%s" wymaga aktywnej integracji. Upewnij się, że wymagana integracja jest zainstalowana i aktywna.','Creating…'=>'Tworzenie…','Creative / Marketing'=>'Kreatywny / Marketing','Creative / Marketing instructions'=>'Instrukcje kreatywne / marketingowe','Current content (will be overwritten)'=>'Aktualna treść (zostanie nadpisana)','Current status'=>'Aktualny status','Current title'=>'Aktualny tytuł','Current: {current}'=>'Aktualne: {current}','Currently emitting'=>'Obecnie emitowane','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Obecnie dziedziczone z constanty %s. Wybranie wartości tutaj nadpisze to.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Obecnie pomijane dla wpisów korzystających z atrybutów blok-comment (np. wp:details, pola podsumowania) — przechodzą do istniejącej ścieżki tłumaczenia wywołania pojedynczego.','Currently:'=>'Obecnie:','Custom'=>'Niestandardowe','Custom tables — LF post-meta filters do not affect orders.'=>'Niestandardowe tabele — filtry LF post-meta nie wpływają na zamówienia.','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Dzienne limity AI osiągnięte (%1$d żądań). Reset o %2$s UTC.','Daily quota'=>'Dzienne limity','Daily request limit'=>'Dzienny limit żądań','Danger Zone'=>'Strefa niebezpieczna','Debug Files'=>'Pliki debugowania','Debug files cleared. %d file was removed.'=>'Pliki debugowania wyczyszczone. Usunięto %d plik.' . "\0" . 'Pliki debugowania wyczyszczone. Usunięto %d plików.' . "\0" . '','Debug Info'=>'Informacje debugowania','Debug logging'=>'Logowanie debugowania','Debug logging disabled.'=>'Logowanie debugowania wyłączone.','Debug logging enabled.'=>'Logowanie debugowania włączone.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Debugowanie: włącz dziennik debugowania, aby rejestrować zapytania AI i odpowiedzi API do lokalnego pliku. Wyłącz po rozwiązaniu problemów — tryb debugowania zapisuje plik przy każdym żądaniu AI.','Default OG image'=>'Domyślny obraz OG','Default profile'=>'Domyślny profil','Delete'=>'Usuń','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Czy chcesz usunąć wszystkie pliki .txt w katalogu debugowania? Sam katalog pozostanie, aby przyszłe zapisy debugowania mogły się tam trafiać.','Delete all files for this override (both .mo and .po)?'=>'Usunąć wszystkie pliki dla tego nadpisania (zarówno .mo, jak i .po)?','Delete content data on uninstall'=>'Usuń dane zawartości podczas odinstalowania','Delete this glossary entry?'=>'Czy chcesz usunąć ten wpis słownika?','Describe what to write — topic, key points, structure…'=>'Opisz, co napisać — temat, kluczowe punkty, struktura…','Destructive action — read before proceeding'=>'Działanie destrukcyjne — przeczytaj przed kontynuacją','Details ↗'=>'Szczegóły ↗','Detect active SEO plugins (Yoast, Rank Math, etc.) at runtime. Emit only og:locale + og:locale:alternate when another plugin already outputs the full OG set; emit the complete set when none is detected.'=>'Wykrywanie aktywnych wtyczek SEO (Yoast, Rank Math itp.) podczas działania. Emituj tylko og:locale + og:locale:alternate, gdy inna wtyczka już generuje pełny zestaw OG; emituj pełny zestaw, gdy żadna nie jest wykryta.','Directory'=>'Katalog','Disable only for headless sites or fully custom hreflang implementations. When disabled, LF no longer removes the WordPress core canonical tag and no longer suppresses SEO-plugin hreflang output.'=>'Wyłącz tylko dla stron headless lub w pełni niestandardowych implementacji hreflang. Po wyłączeniu LF nie usuwa już kanonicznego tagu WordPressa i nie tłumi outputu hreflang wtyczek SEO.','Disabled'=>'Wyłączone','Disabled (by setting)'=>'Wyłączone (ustawieniem)','Disabled (mode setting)'=>'Wyłączone (trybem ustawienia)','Disabled because the lf-social-share mu-plugin is already providing this feature.'=>'Wyłączone, ponieważ mu-plugin lf-social-share już zapewnia tę funkcję.','DISALLOW_FILE_MODS is set.'=>'Ustawiono DISALLOW_FILE_MODS.','Display'=>'Wyświetlacz','Displays the Lingua Forge language switcher.'=>'Wyświetla przełącznik języków Lingua Forge.','Do not output any OG tags.'=>'Nie generuj żadnych tagów OG.','Documentation'=>'Dokumentacja','Done'=>'Gotowe','Done — {done} of {total} post(s) fixed.'=>'Zakończono — naprawiono {done} z {total} postów.','Down'=>'Dół','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Pobierz i zainstaluj pakiet językowy WordPress bezpośrednio z WordPress.org. Po instalacji lokalizacja będzie dostępna do routingu URL i workflow tłumaczeń AI. Lista dostępnych języków jest pobierana na żądanie — kliknij przycisk poniżej, aby ją załadować.','Dropdown direction'=>'Kierunek rozwijanego menu','Each metric yields one of four statuses: ok (full weight), warn (50 % of weight), fail (0), or info (0, no penalty). A score ≥ 80 is green, 50–79 amber, below 50 red.'=>'Każda metryka daje jeden z czterech statusów: ok (pełna waga), ostrzeżenie (50% wagi), niepowodzenie (0), lub informacja (0, brak kary). Wynik ≥ 80 jest zielony, 50–79 bursztynowy, poniżej 50 czerwony.','Each post is scored 0–100 from six rule-based metrics: title, meta description, word count, heading structure, image alt coverage, and internal links. Ten points are always awarded for reading time (informational only). The remaining 90 points are distributed across the other metrics with weights that vary by content profile (see below).'=>'Każdy post jest oceniany w skali 0–100 na podstawie sześciu metryk opartych na zasadach: tytuł, meta opis, liczba słów, struktura nagłówków, pokrycie obrazów alt i wewnętrzne linki. Za czas czytania zawsze przyznaje się 10 punktów (tylko informacyjnie). Pozostałe 90 punktów jest rozdzielane pomiędzy pozostałe metryki z wagami zmieniającymi się w zależności od profilu treści (patrz poniżej).','edit'=>'edytuj','Editors and above (edit_others_posts)'=>'Redaktorzy i wyżej (edytuj_inne_posty)','Enable API response caching'=>'Włącz buforowanie odpowiedzi API','Enable block-level translation cache reuse across posts'=>'Włącz ponowne użycie pamięci podręcznej tłumaczeń na poziomie bloków między wpisami','Enable Social Share URL rewriting for Social Icons blocks'=>'Włącz przepisywanie URL społecznego udostępniania dla bloków ikon społecznych','Enable when your theme renders the post title as an H2 instead of an H1 (common in some block themes). The analyser fetches the rendered page and, if it finds no H1 but does find an H2, it promotes the first H2 to H1 for scoring purposes.'=>'Włącz, gdy motyw renderuje tytuł jako H2 zamiast H1 (częste w niektórych motywach blokowych). Analizator pobiera renderowaną stronę i, jeśli nie znajdzie H1, ale znajdzie H2, promuje pierwsze H2 do H1 dla celów oceny.','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Wprowadź swój klucz API dla co najmniej jednego dostawcy AI. Klucze są szyfrowane w spoczynku za pomocą AES-256-GCM z tajnym kluczem specyficznym dla witryny (LINGUAFORGE_SECRET). Nie udostępniaj eksportów bazy danych bez najpierw rotacji sekretu.','Environment'=>'Środowisko','environment variable'=>'zmienna środowiskowa','Error'=>'Błąd','Every time a post is analysed the score is stored in post meta. The post list Lang column shows a colour-coded "SEO N" badge for any post that has been analysed at least once. When two scores are stored a delta indicator (↑N / ↓N) shows the change since the previous run.'=>'Za każdym razem, gdy post jest analizowany, wynik jest przechowywany w meta danych posta. Kolumna języka na liście postów pokazuje kolorową odznakę "SEO N" dla każdego posta, który był analizowany przynajmniej raz. Gdy zapisane są dwa wyniki, wskaźnik delta (↑N / ↓N) pokazuje zmianę od poprzedniego uruchomienia.','Exactly one H1 is required. The H1 is normally the post title rendered by the theme — it is read from the live rendered page when possible, and from post content as a fallback.'=>'Dokładnie jeden H1 jest wymagany. H1 to zazwyczaj tytuł posta renderowany przez motyw — odczytywany z aktualnie wyświetlanej strony, gdy to możliwe, a w razie braku z treści posta.','Exclude from navigation menus'=>'Wyklucz z menu nawigacyjnych','Exclude from routing'=>'Wyklucz z routingu','Exclude this post type from language routing — its posts will no longer appear here or receive _lf_lang. This cannot be undone automatically.'=>'Wyklucz ten typ posta z routingu językowego — jego posty nie będą już wyświetlane tutaj ani nie będą otrzymywać _lf_lang. Nie można tego cofnąć automatycznie.','Exclude this post type from language routing? Its posts will no longer appear in this list or receive _lf_lang. You can reverse this in Settings → Router → Query Filter Exclusions.'=>'Wyklucz ten typ posta z routingu językowego? Jego posty nie będą już wyświetlane na tej liście ani nie będą otrzymywać _lf_lang. Możesz to odwrócić w Ustawieniach → Router → Wykluczenia filtra zapytań.','excluded from routing'=>'wykluczony z routingu','Excluded post types'=>'Wykluczone typy postów','Excluding…'=>'Wykluczanie…','Expand'=>'Rozszerz','Expected: {expected}'=>'Oczekiwane: {expected}','External share services'=>'Zewnętrzne usługi udostępniania','Extra guidance — tone, style, constraints, target audience…'=>'Dodatkowe wskazówki — ton, styl, ograniczenia, grupa docelowa…','Extra guidance — tone, style, constraints…'=>'Dodatkowe wskazówki — ton, styl, ograniczenia…','Failed to save exclusion.'=>'Nie udało się zapisać wykluczenia.','Failed. Please try again.'=>'Nie powiodło się. Spróbuj ponownie.','Fallback image URL used when a page has no featured image, site logo, or site icon. Shown in social previews for archives, the blog index, and any singular page without a thumbnail.'=>'Adres URL obrazka zastępczego używany, gdy strona nie ma wyróżnionego obrazu, logo witryny lub ikonę witryny. Wyświetlany w podglądach społecznościowych dla archiwów, indeksu bloga i dowolnej pojedynczej strony bez miniatury.','Feature'=>'Funkcja','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Funkcje są pogrupowane w dwie warstwy. Wprowadź dokładny identyfikator modelu dla każdej warstwy i dostawcy. Pozostaw pole puste, aby użyć wbudowanego domyślnego (pokazanego jako placeholder). Tylko modele aktywnego dostawcy są wywoływane podczas działania — skonfiguruj pozostałe wcześniej, jeśli planujesz zmianę.','File copied to safe storage successfully.'=>'Plik skopiowany do bezpiecznej pamięci pomyślnie.','File modifications are disabled (DISALLOW_FILE_MODS).'=>'Modyfikacje plików są wyłączone (DISALLOW_FILE_MODS).','Files'=>'Pliki','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'Pliki trafiają do poniższego katalogu. Przydatne do diagnozowania problemów z tłumaczeniem — wyłącz po uzyskaniu potrzebnych danych, aby pliki się nie gromadziły. Możesz też wymusić to z wp-config.php za pomocą `define( \'LINGUAFORGE_AI_DEBUG\', true );`, co nadpisuje ten przełącznik.','Filter'=>'Filtr','Filter by language and post type, browse your content, and click Analyze on any item to run a rule-based SEO audit — title length, meta description, word count, heading structure, image alt coverage, and internal links.'=>'Filtruj według języka i typu posta, przeglądaj treści i kliknij Analizuj na dowolnym elemencie, aby uruchomić audyt SEO oparty na regułach — długość tytułu, meta opis, liczba słów, struktura nagłówków, pokrycie alt obrazów i linki wewnętrzne.','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filtruj za pomocą linguaforge_debug_dir, aby przekierować wyjście debugowania do niepublicznej lokalizacji.','Finding'=>'Wyszukiwanie','Fix'=>'Napraw','Fix All'=>'Napraw wszystko','Fix all links'=>'Napraw wszystkie linki','Fix all parts'=>'Napraw wszystkie części','Fix Links'=>'Napraw linki','Fix Nav'=>'Napraw nawigację','Fix Parts'=>'Napraw części','Fix Template'=>'Napraw szablon','Fixing {n} / {total}…'=>'Naprawa {n} / {total}…','Fixing…'=>'Naprawianie…','Flush Permalink Rules'=>'Wyczyść reguły permalinków','Flush Permalinks'=>'Wyczyść permalinki','Flush Sitemap Cache'=>'Wyczyść pamięć podręczną mapy witryny','Footnote Content'=>'Treść przypisu','footnote(s) translated — applied together with content.'=>'Przetłumaczono przypis(y) — zastosowano razem z treścią.','Footnotes'=>'Przypisy','Footnotes payload (advanced)'=>'Dane odnośników (zaawansowane)','Forbidden'=>'Zabronione','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Wymuszone wyłączenie przez stałą LINGUAFORGE_AI_DEBUG w wp-config.php. Usuń tę linię, aby kontrolować ten przełącznik stąd.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Wymuszone włączenie przez stałą LINGUAFORGE_AI_DEBUG w wp-config.php. Usuń tę linię, aby kontrolować ten przełącznik stąd.','Forces the sitemap to regenerate on the next request. Use after bulk-importing or manually editing translation relationships.'=>'Wymusza ponowne wygenerowanie mapy witryny przy następnym żądaniu. Użyj po masowym imporcie lub ręcznym edytowaniu relacji tłumaczeń.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Znaleziono {parts} wśród <strong>{total}</strong> z <strong>{scanned}</strong> zeskanowanych postów dla <strong>{lang}</strong>.','From'=>'Od','Front Page'=>'Strona główna','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'Lokalizacja FSE: tworzenie szkieletu, tłumaczenie i naprawa linków w szablonach i częściach szablonów Full Site Editing bezpośrednio z tego zakładki.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Szablony FSE utworzone z aktywnego motywu. Utwórz, a następnie dostosuj w Edytorze witryny.','Full'=>'Pełne','Full Article'=>'Pełny artykuł','Full post'=>'Pełny post','Full-page Translation, Content Generator (mid-tier models are fully sufficient)'=>'Tłumaczenie pełnej strony, Generator treści (modele średniego poziomu są w pełni wystarczające)','General'=>'Ogólne','Generate'=>'Generuj','Generate Content'=>'Generuj treść','Generate content…'=>'Generuj treść…','Generate Excerpt'=>'Wygeneruj fragment','Generate Meta Description'=>'Wygeneruj metaopis','Generate the multilingual sitemap at /lf-sitemap.xml'=>'Wygeneruj wielojęzyczną mapę witryny pod /lf-sitemap.xml','Generated Content'=>'Wygenerowana treść','Generated meta description'=>'Wygenerowany meta opis','Generating…'=>'Tworzenie…','Generation failed.'=>'Niepowodzenie generowania.','Getting started'=>'Rozpoczęcie','Global AI preset'=>'Globalny preset AI','Global default (%s)'=>'Domyślny globalny (%s)','Glossary'=>'Słownik','Glossary entry added.'=>'Wpis słownika dodany.','Glossary entry removed.'=>'Wpis słownika usunięty.','Glossary Tab'=>'Zakładka słownika','Google (Gemini)'=>'Google (Gemini)','Google AI Studio'=>'Google AI Studio','H2-as-H1 mode enabled — title counted as H1 equivalent. (Heading tags could not be detected from the rendered page; verify your theme outputs the title correctly.)'=>'Tryb H2 jako H1 włączony — tytuł liczony jako odpowiednik H1. (Tagi nagłówków nie mogły zostać wykryte na renderowanej stronie; sprawdź, czy Twój motyw poprawnie wyświetla tytuł.)','Heading structure rules'=>'Zasady struktury nagłówków','Headings'=>'Nagłówki','Hide'=>'Ukryj','High-Performance Order Storage (HPOS)'=>'Wysokowydajne przechowywanie zamówień (HPOS)','Hints'=>'Wskazówki','Home link text'=>'Tekst linku do strony głównej','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Jak powinna wyglądać w tłumaczeniu. Wpisz tę samą wartość co termin źródłowy, aby nakazać AI zachować ją dosłownie.','How to use'=>'Jak używać','HPOS + CPT synced — transitional; LF post-meta filters apply to CPT copy.'=>'HPOS + CPT zsynchronizowane — przejściowo; filtry LF post-meta mają zastosowanie do kopii CPT.','Hreflang'=>'Hreflang','Hreflang output'=>'Wynik hreflang','Hreflang settings saved.'=>'Ustawienia hreflang zapisane.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Ikona + etykieta','Icon only'=>'Tylko ikona','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Jeśli zaznaczysz, odinstalowanie wtyczki trwale usunie wszystkie przypisania językowe, relacje tłumaczeń, meta opisy, ustawienia na stronie, glosariusz AI i pamięć tłumaczeń dla każdego posta na tej stronie. Nie można tego cofnąć. Odznacz, jeśli chcesz całkowicie usunąć obsługę wielojęzyczności ze strony.','If you have a general SEO plugin installed, this panel shows how LF adapts to avoid duplicate output. The goal is collision avoidance — not cooperation. LF always provides the multilingual SEO layer (hreflang, og:locale, inLanguage schema) that requires knowledge of LF\'s language routing configuration to produce correctly.'=>'Jeśli masz zainstalowaną ogólną wtyczkę SEO, ten panel pokazuje, jak LF dostosowuje się, aby uniknąć duplikacji outputu. Celem jest unikanie kolizji — nie współpraca. LF zawsze zapewnia wielojęzyczną warstwę SEO (hreflang, og:locale, schema inLanguage), która wymaga znajomości konfiguracji routingu językowego LF, aby poprawnie generować.','If you have Yoast SEO, Rank Math, All in One SEO, or SEOPress installed, Lingua Forge detects them and adapts to avoid duplicate output. For hreflang, LF takes over entirely and suppresses the plugin\'s output because those plugins cannot produce correct hreflang for a multilingual routing configuration. For Open Graph, LF adds only og:locale and og:locale:alternate — the multilingual signals the plugin cannot provide — and leaves the base OG set to the plugin. For Schema.org, LF disables its own output entirely to avoid conflicting JSON-LD graphs.'=>'Jeśli masz zainstalowane Yoast SEO, Rank Math, All in One SEO lub SEOPress, Lingua Forge wykrywa je i dostosowuje, aby uniknąć duplikacji outputu. Dla hreflang LF całkowicie przejmuje kontrolę i tłumi output wtyczki, ponieważ te wtyczki nie mogą poprawnie generować hreflang dla wielojęzycznej konfiguracji routingu. Dla Open Graph LF dodaje tylko og:locale i og:locale:alternate — sygnały wielojęzyczności, których wtyczka nie może zapewnić — i pozostawia podstawowy zestaw OG w wtyczce. Dla Schema.org LF całkowicie wyłącza własny output, aby uniknąć konfliktów w grafach JSON-LD.','Images'=>'Obrazy','Improve writing'=>'Popraw pisanie','In the block editor, add a Social Icons block. For each icon, open the link settings and enter one of the "share:" values below as the URL. On the frontend, LF replaces it with the correct share URL for the current page.'=>'W edytorze bloków dodaj blok ikon społecznych. Dla każdej ikony otwórz ustawienia linku i wpisz jedną z wartości "share:" poniżej jako URL. Na stronie LF zastępuje to poprawnym URL udostępniania dla bieżącej strony.','Includes name, description, inLanguage, url, image, and an Offer with price, priceCurrency, and availability. Price and availability come from the source-language product (shared stock model).'=>'Zawiera nazwę, opis, inLanguage, URL, obraz i ofertę z ceną, walutą i dostępnością. Cena i dostępność pochodzą z produktu w języku źródłowym (model zapasów dzielonych).','Includes site name, url, and inLanguage.'=>'Zawiera nazwę witryny, URL i inLanguage.','Informative'=>'Informacyjne','Input tokens'=>'Tokeny wejściowe','Install'=>'Zainstaluj','Install a Language'=>'Zainstaluj język','Installed SEO plugins'=>'Zainstalowane wtyczki SEO','Installing…'=>'Instalacja…','instock / oos / pending from WC stock status'=>'w magazynie / brak w magazynie / oczekujące z statusu magazynowego WC','Instructions (optional)'=>'Instrukcje (opcjonalnie)','Instructions / key points'=>'Instrukcje / kluczowe punkty','Integration API'=>'API integracji','Internal Link Fixer'=>'Naprawiacz linków wewnętrznych','Introduction only'=>'Tylko wprowadzenie','Invalid API key — double-check the key entered in the AI Provider settings.'=>'Nieprawidłowy klucz API — sprawdź dwukrotnie klucz w ustawieniach dostawcy AI.','Invalid file reference.'=>'Nieprawidłowe odniesienie do pliku.','Invalid filename.'=>'Nieprawidłowa nazwa pliku.','Invalid language code.'=>'Nieprawidłowy kod języka.','Invalid language.'=>'Nieprawidłowy język.','Invalid locale code.'=>'Nieprawidłowy kod lokalizacji.','Invalid or primary language.'=>'Nieprawidłowy lub główny język.','Invalid post ID.'=>'Nieprawidłowy identyfikator posta.','Invalid post type.'=>'Nieprawidłowy typ wpisu.','Invalid template part.'=>'Nieprawidłowa część szablonu.','Invalid template type.'=>'Nieprawidłowy typ szablonu.','JavaScript-powered actions'=>'Akcje oparte na JavaScript','Just now'=>'Właśnie teraz','Key points, ideas, or structure to build from…'=>'Kluczowe punkty, pomysły lub struktura do zbudowania...','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Klucze są szyfrowane za pomocą AES-256-CBC przed zapisaniem w bazie danych WordPress. Sekret szyfrowania pochodzi z Twoich soli uwierzytelniania WordPress (wp-config.php), więc klucze w formacie tekstowym nigdy nie trafiają do bazy danych.','Landing / Short-form'=>'Strona docelowa / Krótka forma','Language'=>'Język','Language %s installed successfully.'=>'Język %s został pomyślnie zainstalowany.','Language (optional)'=>'Język (opcjonalnie)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Instalacja języków jest wyłączona na tym serwerze (ustawiono DISALLOW_FILE_MODS).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Instalacja języków jest wyłączona na tym serwerze. Stała DISALLOW_FILE_MODS jest ustawiona w wp-config.php. Zainstaluj pakiety językowe ręcznie za pomocą WP-CLI: wp language core install de_DE','Language label'=>'Etykieta języka','Language Overrides'=>'Nadpisywanie języka','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Nadpisywanie języków: zarządzaj niestandardowymi plikami .po/.mo dla tekstów interfejsu Lingua Forge. Używaj tego zamiast bezpośredniej edycji plików wtyczki — nadpisy zachowują się po aktualizacjach.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Niepowodzenie instalacji pakietu językowego. Język może być już zainstalowany, kod lokalizacji może być niepoprawny lub serwer może blokować zapisy plików.','Language Setup'=>'Ustawienia języka','Language Switcher'=>'Przełącznik języków','Language switcher'=>'Przełącznik języków','Language uninstalled. %d post deleted.'=>'Język odinstalowany. %d post usunięty.' . "\0" . 'Język odinstalowany. %d postów usuniętych.' . "\0" . '','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Kopie części szablonów tematu specyficzne dla języka. Po utworzeniu, szablony są aktualizowane, aby odwoływały się do części specyficznej dla języka.','Language:'=>'Język:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Języki obecnie znane routerowi (pochodzące z zainstalowanych pakietów lokalizacyjnych WordPress oraz główny język). Zainstaluj dodatkowe pakiety językowe w poniższej sekcji, aby udostępnić więcej języków do routingu i tłumaczeń.','Last 30 days'=>'Ostatnie 30 dni','Last 7 days'=>'Ostatnie 7 dni','Last generated: %s'=>'Ostatnia generacja: %s','Last rule-based SEO score. Run analysis in Settings → SEO → Analysis to update.'=>'Ostatni wynik SEO oparty na regułach. Uruchom analizę w Ustawienia → SEO → Analiza, aby zaktualizować.','Last run: %s ago'=>'Ostatnio uruchomione: %s temu','Lead paragraph (≤60 w)'=>'Wstępny akapit (≤60 sł)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Pozostaw pole modelu puste, aby użyć wbudowanego domyślnego dla tego poziomu. Tekst zastępczy pokazuje, który model będzie używany.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Pozostaw puste dla nazw marek i terminów niezależnych od języka, które mają być egzekwowane bez względu na język tłumaczenia.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Pozostaw puste, aby zastosować tę pozycję do wszystkich języków docelowych — idealne dla nazw marek, skrótów i terminów, które muszą być zachowane dosłownie w każdym tłumaczeniu.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Pozostaw puste, aby zachować istniejący klucz. Wprowadź nową wartość, aby go zastąpić.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Pozostaw puste, aby użyć wbudowanego domyślnego ustawienia. Wyczyszczenie zapisanej nadpisanej wartości przywraca domyślną wartość przy następnym zapisie.','Legacy lf-social-share mu-plugin'=>'Legacy mu-plugin lf-social-share','Legacy lf-social-share mu-plugin detected. LF is deferring the base OG set to the mu-plugin and outputting og:locale + og:locale:alternate only. You can deactivate the mu-plugin — LF\'s built-in Social Share (SEO → Social Share tab) and Open Graph cover the same functionality.'=>'Wykryto legacy mu-plugin lf-social-share. LF odracza podstawowy zestaw OG do mu-plugin i generuje tylko og:locale + og:locale:alternate. Możesz dezaktywować mu-plugin — wbudowany Social Share LF (zakładka SEO → Social Share) i Open Graph pokrywają tę samą funkcjonalność.','Legacy post-based (CPT)'=>'Legacy post-based (CPT)','Legal / Compliance'=>'Prawny / Zgodność','Legal / Compliance instructions'=>'Instrukcje prawne / zgodności','LF always adds og:locale and og:locale:alternate — the multilingual OG signals no general SEO plugin can produce correctly. For the base OG set (og:title, og:description, og:image), LF outputs it when no other plugin is present. When a SEO plugin is installed, LF skips the base set to avoid duplicate tags — not because the plugin is "better", but because duplication produces no value.'=>'LF zawsze dodaje og:locale i og:locale:alternate — wielojęzyczne sygnały OG, które żadna ogólna wtyczka SEO nie może poprawnie wygenerować. Dla podstawowego zestawu OG (og:title, og:description, og:image) LF go generuje, gdy nie ma innej wtyczki. Gdy zainstalowana jest wtyczka SEO, LF pomija podstawowy zestaw, aby uniknąć duplikacji tagów — nie dlatego, że wtyczka jest "lepsza", ale ponieważ duplikacja nie ma wartości.','LF generates its own sitemap with xhtml:link alternates for all translation groups. When a SEO plugin is installed, it generates a separate sitemap — both coexist independently. Submit both to Google Search Console: the SEO plugin sitemap for content discovery, the LF sitemap for language relationship signals.'=>'LF generuje własną mapę witryny z alternatywami xhtml:link dla wszystkich grup tłumaczeń. Gdy zainstalowana jest wtyczka SEO, generuje osobną mapę — obie współistnieją niezależnie. Prześlij obie do Google Search Console: mapa witryny wtyczki SEO do odkrywania treści, mapa witryny LF do sygnałów relacji językowych.','LF is outputting hreflang tags and has removed the WordPress core canonical tag on multilingual pages.'=>'LF generuje tagi hreflang i usunęło kanoniczny tag WordPressa na stronach wielojęzycznych.','LF is suppressing hreflang output from: %s'=>'LF tłumi output hreflang z: %s','LF outputs accurate hreflang for every configured language, including x-default. General SEO plugins have no access to your LF routing configuration and would produce hreflang based on incorrect URL assumptions. LF suppresses their output via filter to prevent collisions.'=>'LF generuje dokładne tagi hreflang dla każdego skonfigurowanego języka, w tym x-default. Wtyczki SEO ogólne nie mają dostępu do konfiguracji routingu LF i mogą generować hreflang na podstawie błędnych założeń URL. LF tłumi ich wyjście za pomocą filtra, aby zapobiec kolizjom.','LF outputs multilingual JSON-LD with inLanguage annotations tied to its language routing configuration. When a SEO plugin is installed, LF disables its own schema entirely: duplicate JSON-LD graphs produce validation errors and there is no clean way to supplement an existing graph.'=>'LF generuje wielojęzyczny JSON-LD z adnotacjami inLanguage powiązanymi z konfiguracją routingu językowego. Gdy zainstalowana jest wtyczka SEO, LF całkowicie wyłącza własny schemat: duplikaty grafów JSON-LD powodują błędy walidacji, a nie ma czystego sposobu na uzupełnienie istniejącego grafu.','LF provides'=>'LF zapewnia','LF removes the WordPress core canonical tag on multilingual pages because the router\'s language-prefixed rewrite rules and the hreflang x-default are the correct canonical signals for a multilingual site. This prevents a double-canonical if a SEO plugin also outputs one. LF does not add its own canonical — the language routing already makes each URL canonical.'=>'LF usuwa tag kanoniczny WordPressa na wielojęzycznych stronach, ponieważ reguły przepisywania z prefiksem językowym routera i hreflang x-default są poprawnymi sygnałami kanonicznymi dla wielojęzycznej strony. Zapobiega to podwójnemu kanonicznemu, jeśli wtyczka SEO również go generuje. LF nie dodaje własnego kanonicznego — routing językowy już czyni każdy URL kanonicznym.','LF-owned entries currently registered in $wp_rewrite->extra_rules_top. Useful for diagnosing 404s or routing conflicts. Copy these when filing a bug report.'=>'Pozycje własności LF obecnie zarejestrowane w $wp_rewrite->extra_rules_top. Przydatne do diagnozowania 404 lub konfliktów routingu. Skopiuj je podczas zgłaszania błędu.','Light'=>'Lekki','Light (default — fast and cost-effective)'=>'Lekki (domyślny — szybki i opłacalny)','Light (fast and cost-effective — Haiku / Flash)'=>'Lekki (szybki i ekonomiczny — Haiku / Flash)','Light model'=>'Lekki model','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Lekki: używany do meta opisów i generowania fragmentów — szybki, niskokosztowy.','Limit results to pages in the given Lingua Forge language code.'=>'Ogranicz wyniki do stron w podanym kodzie języka Lingua Forge.','Limits'=>'Limity','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge dodaje wielojęzyczne routingi, tłumaczenia oparte na AI, tagi hreflang SEO i przełącznik języków do Twojej witryny WordPress.','Lingua Forge adds WooCommerce-specific Open Graph properties to product pages so that sharing a product URL on Facebook, Pinterest, and similar platforms surfaces the correct product type, price, and availability.'=>'Lingua Forge dodaje specyficzne dla WooCommerce właściwości Open Graph do stron produktów, aby udostępnianie URL produktu na Facebooku, Pinterest i podobnych platformach wyświetlało poprawny typ produktu, cenę i dostępność.','Lingua Forge AI Tools'=>'Narzędzia Lingua Forge AI','Lingua Forge extends the WordPress Core Social Icons block with dynamic share URLs. Set any icon\'s link to a "share:" value and LF rewrites it to the correct share URL or JavaScript action at render time — no custom code or third-party plugin required.'=>'Lingua Forge rozszerza blok ikon społecznościowych WordPressa o dynamiczne adresy URL do udostępniania. Ustaw dowolny link ikony na wartość "share:", a LF przepisze go na poprawny URL udostępniania lub akcję JavaScript podczas renderowania — bez konieczności używania własnego kodu lub wtyczek zewnętrznych.','Lingua Forge generates a dedicated XML sitemap at /lf-sitemap.xml that adds language alternate links for all your translated content. This sitemap complements the WordPress core sitemap and any SEO plugin sitemap — it does not replace them.'=>'Lingua Forge generuje dedykowaną mapę witryny XML pod adresem /lf-sitemap.xml, która dodaje alternatywne linki językowe dla wszystkich Twoich przetłumaczonych treści. Ta mapa witryny uzupełnia mapę WordPressa i mapę wtyczek SEO — nie je zastępuje.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin is required.'=>'Lingua Forge to kompletne rozwiązanie SEO wielojęzycznego. Nie jest wymagana żadna dodatkowa wtyczka SEO.','Lingua Forge is a complete multilingual SEO solution. No additional SEO plugin or sitemap plugin is required.'=>'Lingua Forge to kompletne rozwiązanie SEO wielojęzycznego. Nie jest wymagana żadna dodatkowa wtyczka SEO ani mapa witryny.','Lingua Forge outputs <link rel="alternate" hreflang> tags for every configured language on every page, including x-default pointing to the source language. This is the primary multilingual SEO signal for Google and other search engines — no additional SEO plugin is required.'=>'Lingua Forge generuje tagi <link rel="alternate" hreflang> dla każdego skonfigurowanego języka na każdej stronie, w tym x-default wskazujący na język źródłowy. To główny sygnał SEO wielojęzycznego dla Google i innych wyszukiwarek — nie jest wymagana dodatkowa wtyczka SEO.','Lingua Forge outputs Open Graph and Twitter Card meta tags so shared URLs display the correct language, title, description, and image on social platforms.'=>'Lingua Forge generuje meta tagi Open Graph i Twitter Card, dzięki czemu udostępniane URL-e wyświetlają poprawny język, tytuł, opis i obraz na platformach społecznościowych.','Lingua Forge outputs Schema.org JSON-LD structured data so search engines understand your content type, language, and metadata. This is the primary way to communicate inLanguage annotations for multilingual content to Google and other crawlers.'=>'Lingua Forge generuje dane strukturalne JSON-LD Schema.org, aby wyszukiwarki rozumiały typ treści, język i metadane. To główny sposób komunikacji adnotacji inLanguage dla treści wielojęzycznych z Google i innymi robotami.','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge domyślnie ogranicza dwie funkcje Gutenberga, aby zachować spójne zachowanie redakcyjne w różnych językach. Zaznacz tutaj, gdy potrzebujesz pełnych możliwości Gutenberga / FSE.','Lingua Forge scopes secondary WP_Query instances (sidebar widgets, template blocks, plugin lookups) to the active language by injecting a _lf_lang meta constraint. Post types listed here are excluded from that constraint — their queries are always unfiltered.'=>'Lingua Forge ogranicza wtórne instancje WP_Query (widżety boczne, bloki szablonów, wyszukiwania wtyczek) do aktywnego języka poprzez wstrzyknięcie ograniczenia meta _lf_lang. Typy postów wymienione tutaj są wyłączone z tego ograniczenia — ich zapytania są zawsze niefiltrujące.','Lingua Forge Settings'=>'Ustawienia Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge używa dwóch niezależnych warstw pamięci podręcznej, aby uniknąć zbędnych wywołań API AI. Użyj poniższych zakładek, aby sprawdzić i zarządzać każdą z nich.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge używa dwóch poziomów modeli na dostawcę:','Lingua Forge version'=>'Wersja Lingua Forge','Lingua Forge — Quick Translate'=>'Lingua Forge — Szybkie tłumaczenie','Lingua Forge — Settings'=>'Lingua Forge — Ustawienia','Lingua Forge\'s built-in Social Share and Open Graph modules cover all functionality the mu-plugin provides, plus multilingual og:locale support. You can safely deactivate the mu-plugin.'=>'Wbudowane moduły Social Share i Open Graph Lingua Forge obejmują całą funkcjonalność, którą zapewnia mu-plugin, plus obsługę wielojęzycznego og:locale. Możesz bezpiecznie dezaktywować mu-plugin.','Link copied'=>'Link skopiowany','link(s)'=>'link(i)','Links'=>'Linki','Load available languages'=>'Załaduj dostępne języki','Load content'=>'Załaduj treść','Loaded from cache.'=>'Wczytano z pamięci podręcznej.','Loading…'=>'Wczytywanie…','Locale only'=>'Tylko lokalizacja','Locked — a conflicting SEO plugin is active. See the notice above.'=>'Zablokowane — aktywna jest kolidująca wtyczka SEO. Zobacz powiadomienie powyżej.','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate przechowuje własne tłumaczenia w wp-content/languages/loco/ — lokalizacji, którą można cicho wyczyścić podczas aktualizacji WP, reinstalacji wtyczki lub usunięcia Loco Translate. Kopiowanie plików tutaj przenosi je do katalogu Lingua Forge i18n-overrides, który przetrwa te wszystkie zdarzenia i jest automatycznie ładowany przy każdym żądaniu.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Kopiuj do bezpiecznej pamięci','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Najniższa zdolność WordPress do wywoływania funkcji AI. Ograniczenie tego na stronach z wieloma autorami zapobiega uruchamianiu płatnych wywołań AI przez Współtwórców lub konta próbne. Nadpisz per funkcja za pomocą filtra linguaforge_required_capability.','Maintenance'=>'Utrzymanie','Maintenance Tab'=>'Zakładka konserwacji','Make casual'=>'Uczyń nieformalnym','Make concise'=>'Uczyń zwięzłym','Make formal'=>'Uczyń formalnym','Manage your account, review usage, or top up credits:'=>'Zarządzaj swoim kontem, przeglądaj użycie lub doładuj kredyty:','Mark citations needed'=>'Oznacz cytaty jako potrzebne','Max context characters'=>'Maksymalny kontekst','Max hints characters'=>'Maksymalna liczba znaków wskazówek','Max input characters'=>'Maksymalna liczba znaków wejściowych','Max output tokens'=>'Maksymalna liczba tokenów wyjściowych','Maximum characters accepted from the input field. Default: 8 000.'=>'Maksymalna liczba znaków akceptowanych z pola wejściowego. Domyślnie: 8000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Maksymalna liczba znaków istniejącej treści posta przekazywanej do AI jako kontekst startowy, gdy nie podano wskazówek. Domyślnie: 6000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Maksymalna liczba znaków odczytanych z pola wskazówek. Domyślnie: 2000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Maksymalna liczba znaków treści posta przekazywanej do AI. 0 oznacza brak limitu — pełna treść jest zawsze wysyłana (zalecane). Ustaw wartość różną od zera tylko wtedy, gdy twój dostawca ma ograniczone okno kontekstowe. Ostrzeżenie jest zapisywane w dzienniku błędów PHP za każdym razem, gdy treść jest przycinana.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Maksymalna liczba tokenów, które AI może wygenerować w jednej odpowiedzi tłumaczeniowej. Jeśli tłumaczenie jest cicho obcinane na końcu, zwiększ tę wartość. Domyślnie: 16 000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Maksymalna liczba tokenów, które AI może wygenerować na jedno uruchomienie. Zwiększ, jeśli pełne artykuły są obcinane. Domyślnie: 8192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Maksymalna liczba tokenów, które AI może wygenerować na szybkie tłumaczenie. Domyślnie: 2000.','Meta Description'=>'Meta opis','Meta description'=>'Meta opis','Meta Description, Excerpt Generator'=>'Meta Description, Generator fragmentów','Meta Description, Excerpt Generator, quick translate'=>'Meta opis, generator streszczeń, szybkie tłumaczenie','Metric'=>'Metryka','Minimum role'=>'Minimalna rola','Missing'=>'Brakujący','Missing pattern name or language.'=>'Brak nazwy wzoru lub języka.','Mode'=>'Tryb','Model'=>'Model','Model ID'=>'ID modelu','Model tier'=>'Poziom modelu','Models'=>'Modele','Models Tab (General)'=>'Zakładka modeli (Ogólne)','Modified'=>'Zmodyfikowano','Most recent cached block'=>'Ostatni zapisany blok','Most recent cached response'=>'Ostatnia zapisana odpowiedź','Multilingual routing, complete multilingual SEO (hreflang, Open Graph, Schema.org, sitemap), and AI content tools for WordPress. Language detection, URL routing, translation, content generation, and a full SEO layer — no companion plugin required.'=>'Wielojęzyczne routingi, pełne wielojęzyczne SEO (hreflang, Open Graph, Schema.org, mapa strony), oraz narzędzia AI do tworzenia treści dla WordPressa. Wykrywanie języka, routingi URL, tłumaczenia, generowanie treści i pełna warstwa SEO — bez konieczności posiadania dodatkowego wtyczki.','Multilingual SEO'=>'Wielojęzyczne SEO','Multilingual SEO overview'=>'Przegląd wielojęzycznego SEO','My Account'=>'Moje konto','Name'=>'Nazwa','Name displayed in this language. Leave empty to use the source name.'=>'Nazwa wyświetlana w tym języku. Pozostaw puste, aby użyć nazwy źródłowej.','Navigation'=>'Nawigacja','Navigation has no content to translate.'=>'Nawigacja nie zawiera treści do tłumaczenia.','Navigation not found.'=>'Nawigacja nie znaleziona.','Navigation posts are translated via the Router tab, not this button.'=>'Posty nawigacji są tłumaczone przez zakładkę Router, a nie tym przyciskiem.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Tłumaczenie nawigacji wymaga aktywnego dostawcy AI. Skonfiguruj klucz API w zakładce Klucze API.','Navigations'=>'Nawigacje','Network error — could not reach the provider: %s'=>'Błąd sieci — nie można nawiązać kontaktu z dostawcą: %s','Network error — could not reach the WordPress AJAX endpoint.'=>'Błąd sieci — nie można nawiązać kontaktu z punktem końcowym AJAX WordPress.','Network error.'=>'Błąd sieci.','Never run'=>'Nigdy nie uruchamiaj','No %s version found in this translation group.'=>'Nie znaleziono wersji %s w tej grupie tłumaczeń.','No action needed. Google deprecated its sitemap ping endpoint in January 2024 and now discovers sitemaps exclusively via the robots.txt Sitemap: directive — which LF has already configured. Google will pick it up on its next crawl.'=>'Nie wymaga działania. Google wycofało swój punkt końcowy ping mapy witryny w styczniu 2024 i obecnie odkrywa mapy witryny wyłącznie za pomocą dyrektywy Sitemap w robots.txt — którą LF już skonfigurowało. Google pobierze ją podczas następnego indeksowania.','No active plugins detected.'=>'Nie wykryto aktywnych wtyczek.','No AI provider configured.'=>'Nie skonfigurowano dostawcy AI.','No AI provider configured. Add an API key in Settings → API Keys.'=>'Brak skonfigurowanego dostawcy AI. Dodaj klucz API w Ustawienia → Klucze API.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Nie zarejestrowano użycia AI w wybranym oknie (%s). Wybierz szerszy zakres powyżej.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Jeszcze nie zarejestrowano użycia AI. Gdy edytor wykona tłumaczenie, wygeneruje opis meta lub skorzysta z innej funkcji AI, sumy pojawią się tutaj.','No API key configured for this provider.'=>'Dla tego dostawcy nie skonfigurowano klucza API.','No API key configured — enter your key in the AI Provider settings.'=>'Nie skonfigurowano klucza API — wprowadź swój klucz w ustawieniach dostawcy AI.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Brak wbudowanych instrukcji — każda funkcja AI korzysta z własnych dostrojonych domyślnych ustawień. Wypełnij poniższe pole Instrukcje niestandardowe, aby dodać własne zasady dla całej witryny.','No conflicting SEO plugins detected. Lingua Forge is handling all SEO output independently.'=>'Nie wykryto kolidujących wtyczek SEO. Lingua Forge obsługuje cały output SEO niezależnie.','No credits remaining — top up your OpenAI account at platform.openai.com/account/billing.'=>'Brak kredytów — doładuj swoje konto OpenAI na platformie openai.com/account/billing.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Jeszcze nie znaleziono własnych plików Loco Translate. Pojawią się tutaj po zapisaniu tłumaczenia w Loco Translate.','No external OG plugin detected. LF is outputting the full OG + Twitter Card set.'=>'Nie wykryto zewnętrznej wtyczki OG. LF generuje pełny zestaw OG + Twitter Card.','No file was selected.'=>'Nie wybrano pliku.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Brak wpisów słownika pasujących do obecnego filtra. Wyczyść filtr, aby zobaczyć wszystkie wpisy, lub dodaj nowy wpis poniżej.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Brak jeszcze wpisów słownika. Dodaj jeden poniżej, aby zacząć egzekwować terminologię w tłumaczeniach.','No H1 found. Typically the post title is the H1 — verify your theme is outputting it.'=>'Nie znaleziono H1. Zazwyczaj tytuł posta jest H1 — sprawdź, czy Twój motyw go generuje.','No images found in content.'=>'Nie znaleziono obrazów w treści.','No internal links found to update.'=>'Nie znaleziono wewnętrznych linków do aktualizacji.','No key'=>'Brak klucza','No language-specific template parts found to map.'=>'Nie znaleziono części szablonu specyficznych dla języka do mapowania.','No LF meta description set — using excerpt/content.'=>'Nie ustawiono meta opisu LF — używany jest fragment treści.','No LF rewrite rules found. Flush permalinks if this is unexpected.'=>'Nie znaleziono reguł przepisywania LF. Odśwież permalink, jeśli to nieoczekiwane.','No links found.'=>'Nie znaleziono linków.','No links found. Internal links improve crawlability and user navigation.'=>'Nie znaleziono linków. Linki wewnętrzne poprawiają indeksowalność i nawigację użytkowników.','No meta description found. Generate one via the AI meta description feature.'=>'Nie znaleziono meta opisu. Wygeneruj go za pomocą funkcji AI do tworzenia meta opisów.','No navigation references needed updating.'=>'Nie ma potrzeby aktualizacji odwołań do nawigacji.','No override files uploaded yet.'=>'Jeszcze nie przesłano żadnych plików nadpisujących.','No PHP limit'=>'Brak limitu PHP','No physical robots.txt file found. WordPress is generating it virtually and LF\'s Sitemap directive is included automatically.'=>'Nie znaleziono fizycznego pliku robots.txt. WordPress generuje go wirtualnie, a dyrektywa Sitemap LF jest automatycznie dołączona.','No published posts found for the selected filters.'=>'Nie znaleziono opublikowanych postów dla wybranych filtrów.','No response from AI provider. Check your API key and try again.'=>'Brak odpowiedzi od dostawcy AI. Sprawdź klucz API i spróbuj ponownie.','No response from provider — check the error log for details.'=>'Brak odpowiedzi od dostawcy — sprawdź dziennik błędów po szczegóły.','No secondary languages configured.'=>'Nie skonfigurowano języków dodatkowych.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Brak skonfigurowanych języków drugorzędnych. Zainstaluj pakiet językowy powyżej, aby włączyć szablony.','No source content found to translate.'=>'Nie znaleziono treści źródłowej do tłumaczenia.','No source page linked yet.'=>'Jeszcze nie powiązano strony źródłowej.','No template part references needed updating.'=>'Nie ma potrzeby aktualizacji odwołań do części szablonu.','No third-party SEO plugins detected. Lingua Forge handles all multilingual SEO output.'=>'Nie wykryto wtyczek SEO innych firm. Lingua Forge obsługuje wszystkie wielojęzyczne wyjścia SEO.','No title set.'=>'Nie ustawiono tytułu.','No translated content found. The sitemap will populate once posts have been translated.'=>'Nie znaleziono treści przetłumaczonych. Mapa witryny zostanie wypełniona po przetłumaczeniu postów.','No translation found — analyzed the source language version.'=>'Nie znaleziono tłumaczenia — przeanalizowano wersję językową źródłową.','No {lang} translation registered (TRID missing)'=>'Nie zarejestrowano tłumaczenia {lang} (brak TRID)','No — WooCommerce integration class not loaded'=>'Brak — klasa integracji WooCommerce nie załadowana','Not yet generated. The sitemap is built on the first visit to the sitemap URL and cached for 24 hours.'=>'Jeszcze nie wygenerowano. Mapa witryny jest tworzona przy pierwszej wizycie pod adresem URL mapy witryny i jest buforowana na 24 godziny.','Notes'=>'Uwagi','Nothing — all types disabled'=>'Nic — wszystkie typy wyłączone','Notice message'=>'Wiadomość powiadomienia','Notice settings'=>'Ustawienia powiadomień','Notify search engines'=>'Powiadom wyszukiwarki','Numeric permalink structure is not supported.'=>'Struktura permalinków numerycznych nie jest obsługiwana.','OG/Twitter Card tags: handled by LF\'s Open Graph module (SEO → Open Graph & Twitter Cards)'=>'Tagi OG/Twitter Card: obsługiwane przez moduł Open Graph LF (SEO → Open Graph & Twitter Cards)','Oldest cached block'=>'Najstarszy zapisany blok','Oldest cached response'=>'Najstarsza zapisana odpowiedź','Only .mo files are accepted.'=>'Akceptowane są tylko pliki .mo.','Open Graph'=>'Open Graph','Open Graph &amp; Twitter Cards'=>'Karty Open Graph i Twitter','Open Graph output'=>'Wynik Open Graph','Open Graph settings saved.'=>'Ustawienia Open Graph zapisane.','Open Search Console →'=>'Otwórz Search Console →','Open the browser\'s native Web Share sheet (iOS, Android, some desktops). Falls back to clipboard copy if not supported.'=>'Otwórz natywny arkusz udostępniania w przeglądarce (iOS, Android, niektóre desktopy). W przypadku braku obsługi, kopiuje do schowka.','OpenAI (GPT)'=>'OpenAI (GPT)','OpenAI Platform'=>'Platforma OpenAI','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Opcjonalny kontekst dla redaktorów (np. "ASIC = układ scalony specjalistyczny; zachować w języku angielskim w kontekstach technicznych").','Optional. Bing already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Opcjonalnie. Bing już odczytuje dyrektywę Sitemap: z robots.txt — to tylko wymusza natychmiastowe ponowne indeksowanie zamiast czekać na kolejną zaplanowaną kontrolę.','Optional. Yandex already reads the Sitemap: directive from robots.txt — this just triggers an immediate recrawl instead of waiting for the next scheduled check.'=>'Opcjonalnie. Yandex już odczytuje dyrektywę Sitemap: z robots.txt — to tylko wymusza natychmiastowe ponowne indeksowanie zamiast czekać na kolejną zaplanowaną kontrolę.','Order storage'=>'Przechowywanie zamówień','Orders in wp_posts — ensure shop_order is excluded from LF routing.'=>'Zamówienia w wp_posts — upewnij się, że shop_order jest wykluczony z routingu LF.','Output'=>'Wynik','Output Article or WebPage schema on singular posts and pages'=>'Wynik schematu Article lub WebPage na pojedynczych postach i stronach','Output hreflang tags in wp_head'=>'Wynik tagów hreflang w wp_head','Output mode'=>'Tryb wyjścia','Output Open Graph tags in wp_head'=>'Wynik tagów Open Graph w wp_head','Output Product schema on WooCommerce product pages'=>'Wynik schematu Product na stronach produktów WooCommerce','Output Schema.org JSON-LD in wp_head'=>'Wypisz schemat JSON-LD Schema.org w wp_head','Output tokens'=>'Tokeny wyjściowe','Output WebSite schema on the front page and blog index'=>'Wypisz schemat WebSite na stronie głównej i na stronie bloga','Overall SEO score'=>'Ogólna ocena SEO','overridden'=>'nadpisane','Override file deleted.'=>'Plik nadpisania został usunięty.','Override file uploaded successfully.'=>'Nadpisanie pliku zostało pomyślnie przesłane.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Nadpisuje preset AI dla tłumaczenia i generowania treści na tej stronie. Wszystkie inne funkcje zawsze korzystają z globalnego preset.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Nadpisuje preset AI dla tłumaczenia i generowania treści na tej stronie. Instrukcje niestandardowe dla całej witryny (Ustawienia → Zachowanie) są zawsze dodawane do każdego żądania, niezależnie od tego wyboru.','Overview'=>'Przegląd','Page'=>'Strona','Part'=>'Część','Paste a footnote, sentence, or any snippet here…'=>'Wklej tutaj przypis, zdanie lub dowolny fragment…','Paste text, or select text in the editor first…'=>'Wklej tekst lub najpierw zaznacz tekst w edytorze…','Paste text, or select text on the page first…'=>'Wklej tekst lub najpierw zaznacz tekst na stronie…','Paste your API key…'=>'Wklej swój klucz API…','Path prefix (/de/)'=>'Przedrostek ścieżki (/de/)','Path prefix — example.com/de/'=>'Przedrostek ścieżki — example.com/pl/ lub example.com/de/ (w zależności od języka)','Path routing requires a post-name based permalink structure. Change it in'=>'Routing ścieżki wymaga struktury permalinków opartej na nazwie wpisu. Zmień to w','Pattern'=>'Wzór','Pattern has no content to translate.'=>'Wzór nie ma treści do tłumaczenia.','Pattern not found.'=>'Wzór nie został znaleziony.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>'Wzór został przetłumaczony i zapisany. Skopiuj treść do swojego wpisu CPT za pomocą edytora bloków lub użyj go jako punktu wyjścia dla wielokrotnego bloku.','Pattern translation failed.'=>'Tłumaczenie wzorca nie powiodło się.','Payment required — your account has no remaining credits.'=>'Wymagana płatność — Twoje konto nie ma już dostępnych kredytów.','Per-Post Analysis'=>'Analiza dla każdego wpisu','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Entries are invalidated automatically when the content or AI provider/model changes.'=>'Pamięć podręczna dla każdego wpisu dla tłumaczeń generowanych przez AI, opisów meta, fragmentów i treści. Pozycje są automatycznie unieważniane, gdy treść lub dostawca/model AI się zmieniają.','Permalink rules flushed successfully.'=>'Pomyślnie wyczyszczono reguły permalinków.','Permalink Structure'=>'Struktura permalinków','Permalink structure is compatible with Lingua Forge path routing.'=>'Struktura permalinków jest kompatybilna z routingiem ścieżek Lingua Forge.','Permanently deletes all templates, template parts, patterns, navigation menus, posts, pages, custom post types, products, and product variations associated with this language. Also removes the WordPress locale pack files so this language no longer appears in the router. This action cannot be undone.'=>'Trwale usuwa wszystkie szablony, części szablonów, wzorce, menu nawigacyjne, wpisy, strony, niestandardowe typy wpisów, produkty i warianty produktów powiązane z tym językiem. Usuwa również pliki pakietu lokalizacji WordPress, więc ten język nie pojawia się już w routerze. Ta akcja jest nieodwracalna.','Permanently uninstall %s? This will delete all translated content for this language and cannot be undone.'=>'Czy na pewno chcesz odinstalować %s? Spowoduje to usunięcie całej przetłumaczonej treści dla tego języka i nie można tego cofnąć.','Permission denied.'=>'Odmowa dostępu.','Persuasive'=>'Przekonywujące','PHP constant'=>'stała PHP','PHP max_execution_time'=>'Maksymalny czas wykonywania PHP','PHP memory_limit'=>'Limit pamięci PHP','PHP version'=>'Wersja PHP','Pin on Pinterest'=>'Przypnij na Pinterest','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Przypnij terminy, które nie mogą być tłumaczone lub muszą zawsze być renderowane w określony sposób (np. nazwy marek, nazwy produktów, akronimy). Ograniczenia glosariusza są wstrzykiwane do każdego żądania tłumaczenia AI dla wszystkich funkcji: tłumaczenia postów, meta opisów, fragmentów i tłumaczeń szablonów FSE.','Ping Bing'=>'Ping Bing','Ping Yandex'=>'Ping Yandex','Plain language'=>'Język prosty','Plain permalinks are not supported.'=>'Proste permalinków nie są obsługiwane.','Please enter some instructions first…'=>'Najpierw wprowadź instrukcje…','Please enter some text first…'=>'Najpierw wprowadź tekst…','Plugin'=>'Wtyczka','Post'=>'Post','Post not found or not published.'=>'Nie znaleziono lub nie opublikowano wpisu.','Post not found.'=>'Nie znaleziono wpisu.','Post on X / Twitter'=>'Wpis na X / Twitter','Post type'=>'Typ wpisu','Post type slugs separated by commas or newlines. Changes take effect immediately on save — no permalink flush required.'=>'Skróty typu post oddzielone przecinkami lub nowymi liniami. Zmiany obowiązują natychmiast po zapisaniu — nie jest wymagana odświeżanie permalinków.','Post Types'=>'Typy postów','Posts without _lf_lang are invisible to every Lingua Forge language filter. This can happen when content is imported or created before the plugin was activated.'=>'Wpisy bez _lf_lang są niewidoczne dla każdego filtra językowego Lingua Forge. Może się tak dziać podczas importu treści lub tworzenia przed aktywacją wtyczki.','Prefilled from excerpt. Edit to override.'=>'Wstępnie wypełnione z fragmentu. Edytuj, aby nadpisać.','Price and availability always reflect the source-language product (shared stock model). Tags are only output when LF\'s Open Graph module is set to "Full" or "Auto" mode with no conflicting SEO plugin detected.'=>'Cena i dostępność zawsze odzwierciedlają produkt w języku źródłowym (model wspólnego stanu magazynowego). Tagów używa się tylko wtedy, gdy moduł Open Graph LF jest ustawiony na "Full" lub "Auto" i nie wykryto konfliktującej wtyczki SEO.','Primary content language'=>'Główny język treści','Primary Language'=>'Główny język','Primary language'=>'Główny język','Primary language saved.'=>'Zapisano główny język.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Język główny: język, w którym napisane są Twoje istniejące treści. Wszystkie tłumaczenia są tworzone z tego języka; zmiana go nie przenosi ani nie usuwa żadnych postów.','Processing…'=>'Przetwarzanie…','Product'=>'Produkt','Product / eCommerce'=>'Produkt / eCommerce','Product Open Graph'=>'Open Graph produktu','Product — WooCommerce product pages'=>'Produkt — strony produktów WooCommerce','Profile'=>'Profil','Profiles adapt thresholds and weights to the type of content being analysed. Profile is resolved automatically; you can override it per analysis run from the profile dropdown.'=>'Profile dostosowują progi i wagi do rodzaju analizowanej treści. Profil jest rozwiązywany automatycznie; możesz go nadpisać dla każdej analizy z menu rozwijanego profilu.','Provider'=>'Dostawca','Provider error (HTTP %1$d): %2$s'=>'Błąd dostawcy (HTTP %1$d): %2$s','Provider returned no response. Check the WordPress error log for details.'=>'Dostawca nie zwrócił odpowiedzi. Sprawdź dziennik błędów WordPressa po szczegóły.','Provider service temporarily unavailable — try again in a moment.'=>'Usługa dostawcy tymczasowo niedostępna — spróbuj ponownie za chwilę.','Quality'=>'Jakość','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Jakość (domyślnie — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Jakość (Sonnet / GPT-4o / Gemini Pro)','Quality model'=>'Model jakości','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Jakość: używana do tłumaczeń postów i generowania treści — wyższa jakość, wyższy koszt.','Query Filter Exclusions'=>'Wyłączenia filtrów zapytań','Quick Translate'=>'Szybkie tłumaczenie','Quick Translation'=>'Szybkie tłumaczenie','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Szybkie tłumaczenie jest używane w trybie fragmentów — krótkie fragmenty tłumaczone na żądanie z paska narzędzi, edytora lub wyskakujących okienek bloków. Używa osobnej, lżejszej konfiguracji od pełnoekranowego tłumaczenia, aby zachować szybkość i opłacalność odpowiedzi.','Rate limited — too many requests sent to the provider; wait a moment and try again.'=>'Ograniczenie szybkości — zbyt wiele żądań wysłanych do dostawcy; odczekaj chwilę i spróbuj ponownie.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Ponownie włącza canLockBlocks Gutenberga. Przydatne dla szablonów redakcyjnych, które muszą zapobiegać przesuwaniu lub usuwaniu określonych bloków.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Ponownie włącza supportsTemplateMode. Kluczowe dla pełnych przepływów pracy edycji całej strony, gdzie celowo nadpisuje się szablony na poziomie wpisu.','Re-generates and updates the cached result.'=>'Ponownie generuje i aktualizuje zapisany wynik.','Re-scan'=>'Ponowne skanowanie','Re-scanning…'=>'Ponowne skanowanie…','Re-translate'=>'Ponowne tłumaczenie','Reading time'=>'Czas czytania','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Przekieruj odwiedzających do ich preferowanego języka na podstawie nagłówka Accept-Language przeglądarki','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Dopracuj dalej — np. "zrób to krótsze" lub "użyj formalnego tonu"…','Refine further:'=>'Dalsza poprawa:','Refinement'=>'Dopracowywanie','Refinement failed — please try again.'=>'Nie udało się dopracować — spróbuj ponownie.','Refining…'=>'Dopracowywanie…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Regeneruje reguły przepisywania WordPress, aby prefiksy URL, specyficzne dla języka slug i przepisywanie archiwów były zsynchronizowane. Konieczne po zmianie głównego języka lub dodaniu nowego wsparcia językowego.','Remove stored key'=>'Usuń zapisany klucz','Repair failed.'=>'Naprawa nie powiodła się.','Repair tags every routable post listed above with _lf_lang = %s. Posts in routing-excluded post types are not touched. Only run this after importing content or on initial activation — do not use as a bulk language-reassignment tool.'=>'Napraw tagi każdego postu możliwego do routowania wymienionego powyżej z _lf_lang = %s. Posty w wykluczonych typach postów nie są modyfikowane. Uruchom to tylko po imporcie treści lub przy pierwszym uruchomieniu — nie używaj jako narzędzia do masowego przypisywania języków.','Repair — assign _lf_lang = %s to all routable posts above'=>'Napraw — przypisz _lf_lang = %s wszystkim postom możliwym do routowania powyżej','Repairing…'=>'Naprawa…','Report an issue on GitHub'=>'Zgłoś problem na GitHubie','Request failed — please try again.'=>'Żądanie nie powiodło się — spróbuj ponownie.','Request failed.'=>'Żądanie nie powiodło się.','Request failed. Check your connection.'=>'Niepowodzenie żądania. Sprawdź połączenie.','Request failed. Please try again.'=>'Niepowodzenie żądania. Spróbuj ponownie.','Requests'=>'Żądania','requests / day'=>'żądania / dzień','Reset'=>'Resetuj','Result will appear here…'=>'Wynik pojawi się tutaj…','Retranslate'=>'Przetłumacz ponownie','Retranslating…'=>'Ponowne tłumaczenie…','Review carefully — links and slugs not updated.'=>'Dokładnie sprawdź — linki i slug nie zostały zaktualizowane.','Review translation before applying'=>'Przejrzyj tłumaczenie przed zastosowaniem','Revise'=>'Przegląd','Revision'=>'Rewizja','Revision Type'=>'Typ rewizji','Rewrite Rules'=>'Reguły przepisywania','robots.txt'=>'robots.txt','robots.txt updated with Sitemap directive.'=>'robots.txt zaktualizowany z dyrektywą Sitemap.','Router'=>'Router','Router Tab'=>'Zakładka routera','Run a full SEO audit across all published posts for one or all active languages. Scores are saved per post and reflected in the Language column badges in the post list.'=>'Przeprowadź pełny audyt SEO dla wszystkich opublikowanych wpisów dla jednego lub wszystkich aktywnych języków. Wyniki są zapisywane dla każdego wpisu i odzwierciedlają się w odznakach kolumny Język na liście wpisów.','Run AI Analysis'=>'Uruchom analizę AI','Save'=>'Zapisz','Save analysis settings'=>'Zapisz ustawienia analizy','Save Debug Setting'=>'Zapisz ustawienia debugowania','Save Hreflang Settings'=>'Zapisz ustawienia Hreflang','Save Open Graph Settings'=>'Zapisz ustawienia Open Graph','Save Router Settings'=>'Zapisz ustawienia routera','Save Schema.org Settings'=>'Zapisz ustawienia Schema.org','Save Settings'=>'Zapisz ustawienia','Save Sitemap Settings'=>'Zapisz ustawienia mapy witryny','Save Social Share Settings'=>'Zapisz ustawienia udostępniania społecznościowego','Save the post to persist changes.'=>'Zapisz wpis, aby zachować zmiany.','Save Uninstall Setting'=>'Zapisz ustawienie odinstalowania','Save WooCommerce SEO Settings'=>'Zapisz ustawienia SEO WooCommerce','Saved to the meta description field when you apply.'=>'Zapisano w polu meta opisu po zastosowaniu.','Scan failed: '=>'Nieudane skanowanie: ','Scan request failed. Please try again.'=>'Żądanie skanowania nie powiodło się. Spróbuj ponownie.','Scanning posts for broken language links…'=>'Skanowanie postów w poszukiwaniu uszkodzonych linków językowych…','Schema output deferred.'=>'Wynik schematu odroczony.','Schema.org'=>'Schema.org','Schema.org JSON-LD'=>'JSON-LD Schema.org','Schema.org output'=>'Wynik schema.org','Schema.org settings saved.'=>'Ustawienia schema.org zapisane.','Score'=>'Wynik','Score computation'=>'Obliczanie wyniku','Score history and badges'=>'Historia wyników i odznaki','Scores are a signal, not a verdict. Some content is structurally limited — very short pages, landing pages with little body text, or pages whose purpose is navigation rather than information may score lower by nature. Use this overview to spot genuine parity gaps across languages, not to chase a number.'=>'Wyniki są sygnałem, a nie werdyktem. Niektóre treści są ograniczone strukturalnie — bardzo krótkie strony, strony docelowe z niewielką treścią, lub strony, których celem jest nawigacja, a nie informacja, mogą mieć niższy wynik z natury. Użyj tego przeglądu, aby zauważyć prawdziwe luki w parytetach między językami, a nie ścigać się za liczbą.','Search'=>'Szukaj','Search Console is useful for monitoring indexing and coverage errors, but is not required for discovery.'=>'Konsola wyszukiwania jest przydatna do monitorowania błędów indeksowania i pokrycia, ale nie jest wymagana do odkrywania.','Search Results'=>'Wyniki wyszukiwania','Security check failed — file path is not permitted.'=>'Nieudana kontrola bezpieczeństwa — ścieżka pliku jest niedozwolona.','See Settings → SEO → Compatibility for the full per-feature behaviour table.'=>'Zobacz Ustawienia → SEO → Kompatybilność, aby uzyskać pełną tabelę zachowań według funkcji.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Wybierz język, aby zarządzać jego szablonami FSE, częściami szablonów i menu nawigacyjnymi.','Select a post and run a detailed SEO audit to see per-metric results and a score for that specific item.'=>'Wybierz wpis i uruchom szczegółowy audyt SEO, aby zobaczyć wyniki dla poszczególnych metryk i wynik dla tego konkretnego elementu.','Select language'=>'Wybierz język','Send via Telegram'=>'Wyślij przez Telegram','Send via WhatsApp'=>'Wyślij przez WhatsApp','SEO'=>'SEO','SEO Analysis'=>'Analiza SEO','SEO character-count info'=>'Informacje o liczbie znaków SEO','SEO plugin(s) detected: %s. LF is outputting og:locale and og:locale:alternate only; the detected plugin handles the full OG set.'=>'Wykryto wtyczkę(i) SEO: %s. LF wyświetla tylko og:locale i og:locale:alternate; wykryta wtyczka obsługuje pełny zestaw OG.','SEO Plugins'=>'Wtyczki SEO','SEO plugins and conflict avoidance:'=>'Wtyczki SEO i unikanie konfliktów:','SEO Score System'=>'System oceniania SEO','SEO Scores'=>'Wyniki SEO','SEO Tab'=>'Zakładka SEO','Server setup (subdomain)'=>'Konfiguracja serwera (subdomena)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Ustawia domyślne zachowanie AI dla wszystkich funkcji w całej witrynie. Poszczególne wpisy mogą to nadpisać dla tłumaczeń i generowania treści za pomocą meta boxa Lingua Forge.','Settings'=>'Ustawienia','Settings saved.'=>'Ustawienia zapisane.','Settings → Permalinks'=>'Ustawienia → Permalinki','Share on Facebook'=>'Udostępnij na Facebooku','Share on LinkedIn'=>'Udostępnij na LinkedIn','Share on Mastodon'=>'Udostępnij na Mastodon','Share via email (mailto:)'=>'Udostępnij przez e-mail (mailto:)','Shared / compatibility mode'=>'Tryb współdzielony / kompatybilności','Shop'=>'Sklep','Short content (3 paragraphs or fewer) is never penalised for missing subheadings, regardless of profile. A concise page does not benefit from forced heading structure.'=>'Krótka treść (do 3 akapitów) nigdy nie jest karana za brak podtytułów, niezależnie od profilu. Zwięzła strona nie korzysta na wymuszonej strukturze nagłówków.','Show home link'=>'Pokaż link do strony głównej','Shown when no translation exists for the visitor\'s language.'=>'Wyświetlane, gdy nie istnieje tłumaczenie dla języka odwiedzającego.','Single'=>'Pojedynczy','Single %s'=>'Pojedynczy %s','Single-word title (%d chars) — adding a second word improves clarity and keyword coverage.'=>'Tytuł jedno słowo (%d znaków) — dodanie drugiego słowa poprawia czytelność i pokrycie słów kluczowych.','Single: %s'=>'Pojedynczy: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Ogólny limit AI na stronie na UTC dzień (liczy zarówno tłumaczenia w Toolbar, jak i rewizje bloków). Licznik resetuje się o północy UTC. Ustaw na 0, aby wyłączyć limit.','Sitemap'=>'Mapa witryny','Sitemap cache flushed. It will be regenerated on the next visit to the sitemap URL.'=>'Pamięć podręczna mapy witryny wyczyszczona. Zostanie ona odtworzona przy następnej wizycie pod adresem URL mapy witryny.','Sitemap output'=>'Wynik mapy witryny','Sitemap settings saved.'=>'Ustawienia mapy witryny zapisane.','Sitemap URL'=>'URL mapy witryny','Size'=>'Rozmiar','Social Icons block share: URLs: handled by LF\'s built-in Social Share (SEO → Social Share)'=>'Udostępnianie bloków ikon społecznościowych: adresy URL: obsługiwane przez wbudowane udostępnianie społecznościowe LF (SEO → Udostępnianie społecznościowe)','Social Share'=>'Udostępnianie społecznościowe','Social Share settings saved.'=>'Ustawienia udostępniania społecznościowego zapisane.','Some link fixes failed.'=>'Niektóre naprawy linków nie powiodły się.','Some nav ref fixes failed.'=>'Niektóre naprawy odwołań nawigacyjnych nie powiodły się.','Some part fixes failed.'=>'Niektóre naprawy części nie powiodły się.','Some parts could not be created.'=>'Niektórych części nie można utworzyć.','Some templates could not be created.'=>'Niektórych szablonów nie można utworzyć.','Some translations failed.'=>'Niektóre tłumaczenia nie powiodły się.','source'=>'źródło','Source file not found.'=>'Nie znaleziono pliku źródłowego.','Source lang'=>'Język źródłowy','Source language'=>'Język źródłowy','Source term'=>'Termin źródłowy','Source title'=>'Tytuł źródłowy','Standard'=>'Standardowy','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standard używa własnej dostrojonej temperatury dla każdej funkcji: Tłumaczenie T=0.2 (precyzyjne), Szybkie tłumaczenie T=0.4, Generator treści T=0.6 (kreatywne). Pozostałe preset\'y stosują jedną stałą temperaturę dla wszystkich funkcji.','Start typing in any field to see model suggestions, or use the reference table below. Light and mid-tier Quality models (Haiku, GPT-4o mini, Gemini Flash) are fully sufficient for translation and content generation — flagship "max" models add cost with minimal quality gain for structured text.'=>'Rozpocznij wpisywanie w dowolnym polu, aby zobaczyć sugestie modelu, lub skorzystaj z tabeli odniesienia poniżej. Modele jakości light i mid-tier (Haiku, GPT-4o mini, Gemini Flash) są w pełni wystarczające do tłumaczenia i generowania treści — flagowe modele "max" zwiększają koszty przy minimalnej poprawie jakości dla tekstu strukturalnego.','Status'=>'Status','Status / Actions'=>'Status / Działania','Storytelling'=>'Opowiadanie','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Tryb ścisłego zachowania dla treści prawnych, regulacyjnych, medycznych lub technicznych. Gdy jest włączony, każda funkcja AI używa niskiej temperatury próbkowania i dodaje poniższy dodatek do swojego promptu systemowego — terminologia, numery artykułów, jednostki, nazwy marek i język regulacyjny są zachowywane dokładnie, a nie parafrazowane.','Structured Outline'=>'Strukturalny plan','Subdomain (de.example.com)'=>'Subdomena (de.example.com)','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Tryb subdomen wymaga, aby Twój serwer internetowy kierował wszystkie subdomeny językowe (np. de.example.com) do tej instalacji WordPress. Po zmianie trybu odśwież ustawienia permalinków i wyczyść pamięć podręczną. Jeśli Twój adres URL główny zawiera www (np. www.example.com), użyj filtra lf_base_domain, aby ustawić podstawową domenę, tak aby subdomeny były poprawnie konstruowane.','Subdomain — de.example.com/'=>'Subdomena — pl.example.com/ lub de.example.com/ (w zależności od języka)','Submit this URL to Google Search Console alongside your main sitemap.'=>'Prześlij ten URL do Google Search Console razem z główną mapą witryny.','Submit to Reddit'=>'Prześlij do Reddit','Suggested meta description'=>'Sugerowany meta opis','Suggested title'=>'Sugerowany tytuł','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Obsługiwani dostawcy: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Tylko jeden dostawca jest aktywny naraz. Wybierz aktywnego dostawcę na zakładce Ogólne.','Suppressed: %s.'=>'Wyłączone: %s.','Switch to a post-name based structure in'=>'Przełącz na strukturę opartą na nazwie wpisu w','System'=>'System','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, na funkcję','Tag'=>'Tag','Tags emitted'=>'Emitowane tagi','Target lang'=>'Język docelowy','Target Language'=>'Język docelowy','Target language'=>'Język docelowy','Target term'=>'Termin docelowy','Target: 140–160 chars for optimal SERP display'=>'Docelowo: 140–160 znaków dla optymalnego wyświetlania w SERP','Technical'=>'Techniczne','Technical / Scientific'=>'Techniczny / Naukowy','Technical / Scientific instructions'=>'Instrukcje techniczne / naukowe','Template "%s" already exists.'=>'Szablon "%s" już istnieje.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Szablon "{expected}" nie istnieje — najpierw utwórz go w Edytorze Stron.','Template has no content.'=>'Szablon nie ma treści.','Template mode'=>'Tryb szablonu','Template not found or not stored in the database.'=>'Szablon nie został znaleziony lub nie jest zapisany w bazie danych.','Template part "%s" already exists.'=>'Część szablonu "%s" już istnieje.','Template part has no content.'=>'Część szablonu nie ma treści.','Template part not found or not stored in the database.'=>'Część szablonu nie została znaleziona lub nie jest zapisana w bazie danych.','Template Parts'=>'Części szablonów','Templates'=>'Szablony','Test connection'=>'Testuj połączenie','Testing…'=>'Testowanie…','Text domain / locale'=>'Tekst domeny / lokalizacja','Text to translate'=>'Tekst do tłumaczenia','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them.'=>'Pamięć podręczna odpowiedzi API przechowuje surowy wynik każdego żądania AI — tłumaczenie, opis meta, fragment i generowanie treści — kluczem jest hash wejść (treść, para języków, dostawca, model). Wyłącz podczas dostrajania promptów lub gdy potrzebujesz, aby każde żądanie dotarło do dostawcy AI. Wyłączenie nie usuwa zapisanych wpisów — ponowne włączenie je przywraca.','The editor did not accept the content — please try again.'=>'Redaktor nie zaakceptował treści — spróbuj ponownie.','The following directive is active in your virtual robots.txt:'=>'Następująca dyrektywa jest aktywna w Twoim wirtualnym pliku robots.txt:','The lf-social-share mu-plugin is active.'=>'Wtyczka mu lf-social-share jest aktywna.','The lf-social-share mu-plugin is active. Lingua Forge\'s built-in Social Share is inactive — the mu-plugin handles share URL rewriting and the JS actions.'=>'Wtyczka mu lf-social-share jest aktywna. Wbudowany mechanizm Social Share Lingua Forge jest nieaktywny — wtyczka mu obsługuje przepisywanie URL-i udostępniania i działania JS.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Poziom Light korzysta z szybkiego modelu skonfigurowanego w tabeli modeli powyżej (domyślnie: Haiku / Flash). Przełącz na Jakość, jeśli potrzebujesz takiej samej dokładności tłumaczenia jak w trybie pełnoekranowym dla fragmentów.','The phrase as it appears in the source text.'=>'Fraza tak jak pojawia się w tekście źródłowym.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Główny język jest zawsze dostępny na głównym adresie Twojej strony — brak prefiksu URL w trybie ścieżki, brak subdomeny językowej w trybie subdomeny. Wszystkie pozostałe języki używają albo prefiksu /lang/ (np. example.com/de/), albo subdomeny językowej (np. de.example.com), w zależności od ustawienia struktury URL poniżej.','The SEO → Compatibility tab shows the live detection status and explains exactly what LF is doing for each feature area.'=>'Zakładka SEO → Kompatybilność pokazuje status wykrywania na żywo i wyjaśnia dokładnie, co LF robi dla każdej funkcji.','The share URL always reflects the current page — no manual URL entry needed. The linguaforge_social_share_url filter lets you override the resolved URL for any service.'=>'URL udostępniania zawsze odzwierciedla bieżącą stronę — nie jest potrzebne ręczne wpisywanie URL. filtr linguaforge_social_share_url pozwala nadpisać rozwiązaną URL dla dowolnej usługi.','The sitemap is announced in robots.txt automatically. All major search engines — Google, Bing, Yandex — discover it from robots.txt. No manual submission is required.'=>'Mapa witryny jest automatycznie ogłaszana w robots.txt. Wszystkie główne wyszukiwarki — Google, Bing, Yandex — odkrywają ją z robots.txt. Nie jest wymagana ręczna submisja.','The source page has no footnotes.'=>'Strona źródłowa nie ma przypisów.','The upload failed — please try again.'=>'Przesyłanie nie powiodło się — spróbuj ponownie.','The WordPress core sitemap lists all your content URLs. The LF sitemap tells search engines how language versions relate to each other via xhtml:link hreflang alternates. Submit both to Google Search Console for full coverage.'=>'Mapa witryny WordPress listuje wszystkie Twoje adresy URL treści. Mapa LF informuje wyszukiwarki, jak wersje językowe odnoszą się do siebie za pomocą alternatyw XHTML:link hreflang. Prześlij obie do Google Search Console, aby uzyskać pełne pokrycie.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Te przypisy pochodzą ze strony źródłowej i są wyświetlane tutaj wyłącznie w celach informacyjnych. Dodaj je do tej strony za pomocą edytora bloków.','This catalog is updated with each Lingua Forge release. Testing a connection in the API Keys tab also fetches the live model list from the provider and refreshes the suggestions above.'=>'Ten katalog jest aktualizowany przy każdej wersji Lingua Forge. Testowanie połączenia w zakładce Klucze API również pobiera listę modeli na żywo od dostawcy i odświeża powyższe sugestie.','This is a WooCommerce system page (Shop, Cart, Checkout, etc.). Its content is managed by WooCommerce — the score reflects structural signals only, not user-editable SEO content.'=>'To jest strona systemowa WooCommerce (Sklep, Koszyk, Realizacja zamówienia itp.). Jej treść jest zarządzana przez WooCommerce — wynik odzwierciedla wyłącznie sygnały strukturalne, a nie edytowalną treść SEO.','This is the source page. Footnotes are edited directly in the block editor.'=>'To jest strona źródłowa. Przypisy są edytowane bezpośrednio w edytorze bloków.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Ten klucz jest obecnie dostarczany przez serwer %s i nie można go usunąć tutaj. Wprowadź nowy klucz powyżej, aby nadpisać go wartością z bazy danych.','This language is protected and cannot be uninstalled.'=>'Ten język jest chroniony i nie można go odinstalować.','This language matches the WordPress instance locale and cannot be uninstalled.'=>'Ten język odpowiada lokalizacji instancji WordPress i nie można go odinstalować.','Tier'=>'Poziom','Tip: to reset a model to the built-in default, clear the field and save.'=>'Wskazówka: aby zresetować model do wbudowanego domyślnego, wyczyść pole i zapisz.','Title'=>'Tytuł','Title 15 pts · Meta description 20 pts · Word count 15 pts · Headings 20 pts · Images 10 pts · Links 10 pts. Title SERP limit 60 chars; meta 120–210 chars; word count warns below 300, fails below 100; H2 required; internal links required.'=>'Tytuł 15 pkt · Opis meta 20 pkt · Liczba słów 15 pkt · Nagłówki 20 pkt · Obrazy 10 pkt · Linki 10 pkt. Limit tytułu w SERP 60 znaków; meta 120–210 znaków; ostrzeżenie o liczbie słów poniżej 300, błąd poniżej 100; wymagana H2; wymagane linki wewnętrzne.','Title is %1$d chars — may be truncated in SERPs (aim for under %2$d).'=>'Tytuł ma %1$d znaków — może być obcięty w wynikach wyszukiwania (dążyć do poniżej %2$d).','Title is only %d chars — aim for at least 10 characters.'=>'Tytuł ma tylko %d znaków — staraj się mieć co najmniej 10 znaków.','Title scoring rules (all profiles): fail if empty; warn if fewer than 10 characters; warn if only one word; warn if longer than the profile\'s SERP limit (60 chars for Blog, 70 for Product/Landing); ok if at least 10 characters, at least 2 words, and within the SERP limit.'=>'Zasady oceniania tytułów (wszystkie profile): niepowodzenie jeśli puste; ostrzeżenie jeśli mniej niż 10 znaków; ostrzeżenie jeśli tylko jedno słowo; ostrzeżenie jeśli dłuższy niż limit SERP profilu (60 znaków dla Bloga, 70 dla Produktu/Landing); OK jeśli co najmniej 10 znaków, co najmniej 2 słowa i w limicie SERP.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Aby użyć własnego sekretu szyfrowania (zamiast wyprowadzonej wartości wp_salt), dodaj to do wp-config.php:','Today'=>'Dziś','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are excluded so they don\'t skew the totals.'=>'Zużycie tokenów zsumowane według funkcji, dostawcy i modelu. Rejestrowane przy każdym udanym wywołaniu AI; pingi Test Connection są wykluczone, aby nie zniekształcać sum.','Tone'=>'Ton','tone'=>'ton','Tone:'=>'Ton:','Too many AI requests. Please retry in %d seconds.'=>'Zbyt wiele żądań AI. Spróbuj ponownie za %d sekund.','Total'=>'Razem','Total tokens'=>'Razem tokenów','Translate'=>'Tłumacz','Translate / Revise'=>'Tłumacz / Zrewiduj','Translate / Revise block'=>'Tłumacz / Zrewiduj blok','Translate all'=>'Przetłumacz wszystko','Translate chunk'=>'Tłumacz fragment','Translate Content'=>'Tłumacz treść','Translate missing'=>'Brak tłumaczenia','Translate page…'=>'Tłumacz stronę…','Translated content'=>'Tłumaczona treść','Translated Names'=>'Tłumaczone nazwy','Translated title'=>'Tłumaczony tytuł','Translated to:'=>'Przetłumaczono na:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Przetłumaczono. Przejrzyj w Edytorze Stron — linki wewnętrzne, adresy URL nawigacji i szablony nie są automatycznie aktualizowane.','Translating…'=>'Tłumaczenie w toku…','Translation'=>'Tłumaczenie','Translation Caching'=>'Buforowanie tłumaczeń','Translation found but permalink could not be generated'=>'Znaleziono tłumaczenie, ale nie można wygenerować odnośnika','Translation Limits'=>'Limity tłumaczeń','Translation Limits & Behavior'=>'Limity tłumaczeń i zachowanie','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Limity tłumaczeń: kontroluj, które role użytkowników mogą wywołać tłumaczenie AI, oraz ustaw miesięczny budżet tokenów. Przekroczenie budżetu wstrzymuje wywołania AI do resetu miesiąca.','Translation Memory'=>'Pamięć tłumaczeń','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Pamięć tłumaczeń buforuje wyniki AI na podstawie hasha treści, pary językowej, dostawcy i modelu. Edycja posta unieważnia wpis w pamięci podręcznej, więc następne tłumaczenie pobiera świeży wynik.','Translation Memory cleared. %d cached block was removed.'=>'Pamięć tłumaczeń wyczyszczona. Usunięto %d zbuforowanych bloków.' . "\0" . 'Pamięć tłumaczeń wyczyszczona. Usunięto %d zbuforowanych bloków.' . "\0" . '','Translation Memory setting saved.'=>'Ustawienie pamięci tłumaczeń zapisane.','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Pamięć tłumaczeń: przechowuje pełne przetłumaczone posty na podstawie hasha treści. Wyczyść ją, gdy chcesz wymusić ponowne tłumaczenie wszystkich postów, niezależnie od tego, czy ich treść się zmieniła.','Translation workflow'=>'Przepływ pracy tłumaczeń','Translation, Content Generator'=>'Tłumaczenie, Generator treści','Treat H2 as H1 equivalent'=>'Traktuj H2 jako odpowiednik H1','Type'=>'Typ','Uli Hake'=>'Uli Hake','Unexpected provider error (HTTP %d).'=>'Nieoczekiwany błąd dostawcy (HTTP %d).','Uninstall %s'=>'Odinstaluj %s','Uninstall Behaviour'=>'Odinstaluj zachowanie','Uninstall setting saved.'=>'Ustawienie odinstalowania zapisane.','unknown error'=>'nieznany błąd','Unknown provider.'=>'Nieznany dostawca.','Unknown search engine.'=>'Nieznana wyszukiwarka.','Unlike hreflang — where LF always overrides other plugins because they cannot know your multilingual configuration — Open Graph is different: Yoast, Rank Math, and similar plugins already output correct OG tags for your content. Duplicating them adds no value. In auto mode, LF detects active SEO plugins and adds only what they cannot provide: og:locale (current language) and og:locale:alternate (all other configured languages).'=>'W przeciwieństwie do hreflang — gdzie LF zawsze nadpisuje inne wtyczki, ponieważ nie mogą znać Twojej konfiguracji wielojęzycznej — Open Graph jest inny: Yoast, Rank Math i podobne wtyczki już generują poprawne tagi OG dla Twojej treści. Duplikowanie ich nie dodaje wartości. W trybie automatycznym LF wykrywa aktywne wtyczki SEO i dodaje tylko to, czego nie mogą dostarczyć: og:locale (bieżący język) i og:locale:alternate (wszystkie inne skonfigurowane języki).','Unlimited'=>'Nieograniczony','Up'=>'Góra','Upload .mo file'=>'Prześlij plik .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Prześlij skompilowane pliki .mo, aby nadpisać teksty wtyczek innych firm dla określonych lokalizacji — na przykład własne tłumaczenie VikBooking, które używa "mieszkanie" zamiast "pokój". Pliki muszą mieć nazwę zgodną z konwencją WordPress: {textdomain}-{locale}.mo (np. vikbooking-ca.mo). Są przechowywane w folderze uploads i przetrwają aktualizacje wtyczek.','Upload Override'=>'Prześlij nadpisanie','URL could not be mapped to a post — check the link target exists'=>'Nie można przypisać URL do posta — sprawdź, czy cel linku istnieje','URL structure'=>'Struktura URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Struktura URL: tryb prefiksu ścieżki (example.com/de/) nie wymaga zmian na serwerze. Tryb subdomeny (de.example.com) wymaga rekordu DNS typu wildcard, certyfikatu SSL wildcard oraz zmiany konfiguracji serwera — zobacz przewodnik konfiguracji serwera.','URL to enter'=>'URL do wpisania','Use native share when available; fall back to clipboard copy. Recommended default for "Share" buttons.'=>'Użyj natywnego udostępniania, gdy jest dostępne; w razie potrzeby skopiuj do schowka. Zalecany domyślny dla przycisków "Udostępnij".','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Użyj zakładek na górze tej strony, aby skonfigurować każdą sekcję. Zmiany w zakładce Router są natychmiastowe; zmiany kluczy AI i ustawień modelu obowiązują przy następnym żądaniu AI.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Tablica terminologii zarządzana przez użytkownika dla pary językowej. Wpisy są dodawane do promptu systemu tłumaczeń, aby AI używało preferowanych terminów konsekwentnie — kluczowe dla słownictwa dziedzinowego ("kWp", "PPA", "punkt połączenia"), nazw marek, które nie mogą być tłumaczone, oraz ustandaryzowanej frazeologii regulacyjnej. Oba pola językowe są opcjonalne: pozostaw "Język źródłowy" pusty, aby zastosować wpis niezależnie od języka, z którego tłumaczysz; pozostaw "Język docelowy" pusty, aby zastosować go do wszystkich języków docelowych naraz.','Using custom meta description.'=>'Używanie własnego meta opisu.','Using LF AI meta description.'=>'Używanie meta opisu AI LF.','Value source'=>'Źródło wartości','Version'=>'Wersja','View'=>'Zobacz','View built-in default'=>'Wyświetl wbudowany domyślny','View current robots.txt'=>'Zobacz aktualny robots.txt','View details'=>'Zobacz szczegóły','View Lingua Forge details'=>'Zobacz szczegóły Lingua Forge','Visit plugin site'=>'Odwiedź stronę wtyczki','Warning:'=>'Ostrzeżenie:','WcPageBridge active'=>'Włączony WcPageBridge','WebSite'=>'Strona internetowa','WebSite — front page / blog index'=>'Strona główna / indeks bloga','What LF provides — and collision avoidance'=>'Co zapewnia LF — i unikanie kolizji','What LF provides: hreflang tags for every configured language, Open Graph and Twitter Card tags with og:locale and og:locale:alternate, Schema.org JSON-LD with inLanguage annotations, and a dedicated multilingual sitemap at /lf-sitemap.xml with xhtml:link alternate entries for all translation groups.'=>'Co zapewnia LF: tagi hreflang dla każdego skonfigurowanego języka, tagi Open Graph i Twitter Card z og:locale i og:locale:alternate, Schema.org JSON-LD z adnotacjami inLanguage oraz dedykowana wielojęzyczna mapa witryny pod /lf-sitemap.xml z wpisami alternatywnych odnośników xhtml:link dla wszystkich grup tłumaczeń.','When another SEO plugin is installed'=>'Gdy zainstalowana jest inna wtyczka SEO','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Gdy włączone jest logowanie debugowania (za pomocą przełącznika poniżej lub przez zdefiniowanie LINGUAFORGE_AI_DEBUG w wp-config.php), funkcje tłumaczenia i tłumaczenia szablonów FSE zapisują swoje surowe podpowiedzi AI i odpowiedzi na dysk w celach diagnostycznych. Użyj tej sekcji, aby monitorować ten output i wyczyścić go, gdy będziesz miał to, czego potrzebujesz — pliki mogą szybko się powiększać na dużych stronach. Skonfiguruj katalog docelowy za pomocą filtra linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Po włączeniu, odwiedzający po raz pierwszy, bez pliku cookie języka i bez prefiksu języka w URL, są przekierowywani do najbliższej pasującej wersji językowej. Przekierowanie jest pomijane, jeśli preferowany język przeglądarki nie znajduje się na liście aktywnych języków routera. Po wybraniu języka przez odwiedzającego za pomocą przełącznika, plik cookie ma pierwszeństwo, a nagłówek przeglądarki jest ignorowany przy kolejnych wizytach.','When enabled, Lingua Forge outputs the following additional meta tags on product pages: og:type=product, og:price:amount, og:price:currency, og:availability, and their product: namespace equivalents used by Facebook Catalog.'=>'Po włączeniu, Lingua Forge generuje następujące dodatkowe meta tagi na stronach produktów: og:type=product, og:price:amount, og:price:currency, og:availability oraz ich odpowiedniki w przestrzeni nazw product: używane przez Facebook Catalog.','When enabled, the sitemap URL is announced in robots.txt automatically and the cache is refreshed when translated content is saved.'=>'Po włączeniu, URL mapy witryny jest automatycznie ogłaszany w robots.txt, a pamięć podręczna jest odświeżana po zapisaniu tłumaczonej treści.','When the Blog profile requires an H2 and none is found, the analyser first checks for H3 subheadings before issuing a warning. Accordion and Details blocks default to H3 for their headers; those H3s are accepted as valid structure and produce an ok result, not a warning.'=>'Gdy profil Blog wymaga H2, a nie ma go, analizator najpierw sprawdza podtytuły H3, zanim wyda ostrzeżenie. Bloki Accordion i Details domyślnie mają H3 jako nagłówki; te H3 są akceptowane jako poprawna struktura i dają wynik OK, nie ostrzeżenie.','When Yoast SEO, Rank Math, All in One SEO, or SEOPress is active, Lingua Forge automatically suppresses their hreflang output via filter. General SEO plugins produce hreflang based on a single-language URL structure and cannot account for your multilingual routing configuration; LF\'s output is always correct.'=>'Gdy aktywne są Yoast SEO, Rank Math, All in One SEO lub SEOPress, Lingua Forge automatycznie wyłącza ich generowanie hreflang za pomocą filtra. Ogólne wtyczki SEO generują hreflang na podstawie struktury URL jednolanguage i nie mogą uwzględnić Twojej konfiguracji routingu wielojęzycznego; wyjście LF jest zawsze poprawne.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Który poziom modelu użyć do tłumaczenia pełnej strony. Jakość korzysta z modelu skonfigurowanego w tabeli modeli powyżej i jest zalecana do dokładnego, długiego tłumaczenia. Przełącz na Lekki tylko wtedy, gdy priorytetem jest szybkość lub koszt, a treść jest krótka.','While active, the mu-plugin handles the base OG set and LF emits locale tags only (auto mode). Removing it switches LF to full OG mode automatically.'=>'Podczas aktywności, wtyczka mu obsługuje podstawowy zestaw OG, a LF emituje tylko tagi lokalizacji (tryb automatyczny). Usunięcie go automatycznie przełącza LF na pełny tryb OG.','WooCommerce'=>'WooCommerce','WooCommerce is not active.'=>'WooCommerce nie jest aktywne.','WooCommerce page translations'=>'Tłumaczenia stron WooCommerce','WooCommerce product price'=>'Cena produktu WooCommerce','WooCommerce SEO settings saved.'=>'Ustawienia SEO WooCommerce zapisane.','WooCommerce store currency'=>'Waluta sklepu WooCommerce','WooCommerce system pages (Shop, Cart, Checkout, My Account) are excluded — their content is managed by WooCommerce and cannot be improved through SEO edits.'=>'Strony systemowe WooCommerce (Sklep, Koszyk, Realizacja zamówienia, Moje konto) są wyłączone — ich treść jest zarządzana przez WooCommerce i nie można jej poprawić przez edycję SEO.','WooCommerce version'=>'Wersja WooCommerce','Word count'=>'Liczba słów','WordPress version'=>'Wersja WordPressa','WP core canonical active (hreflang disabled)'=>'Włączony kanoniczny WP (hreflang wyłączony)','WP instance language'=>'Język instancji WP','WP-CLI reference'=>'Odwołanie do WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Zapisuj podpowiedzi i odpowiedzi AI na dysk w celach diagnostycznych','XML Sitemap'=>'Mapa XML','Yes'=>'Tak','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Możesz również definiować klucze jako stałe lub zmienne środowiskowe (np. w wp-config.php). Te źródła są automatycznie używane jako zapasowe, gdy nie ma zapisanej klucza w bazie danych.','You do not have permission to manage these settings.'=>'Nie masz uprawnień do zarządzania tymi ustawieniami.','You do not have permission to read this post.'=>'Nie masz uprawnień do odczytu tego wpisu.','{n} stale path(s)'=>'{n} nieaktualna(e) ścieżka(e)','~%d min read'=>'~%d min czytania' . "\0" . '~%d min czytania' . "\0" . '','— AI features are disabled.'=>'— Funkcje AI są wyłączone.','— Any source language —'=>'— Dowolny język źródłowy —','— Any target language —'=>'— Dowolny język docelowy —','— Any target —'=>'— Dowolny język docelowy —','— Any —'=>'— Dowolny —','— Auto-detect —'=>'— Automatyczne wykrywanie —','— auto-detect —'=>'— automatyczne wykrywanie —','— Deferred to plugin'=>'— Przekierowane do wtyczki','— Disabled'=>'— Wyłączone','— Not detected'=>'— Nie wykryto','— select a language —'=>'— wybierz język —','← Back'=>'← Wstecz','↑ Detected from current post'=>'↑ Wykryto z obecnego wpisu','→ Locale tags only (manual setting)'=>'→ Tagi lokalizacji tylko (ustawienie ręczne)','→ Locale tags only — deferring base OG to plugin'=>'→ Tagi lokalizacji tylko — odroczenie podstawowego OG do wtyczki','↺ Re-translate'=>'↺ Ponowne tłumaczenie','↺ Refine'=>'↺ Ulepszanie','↺ Refresh'=>'↺ Odśwież','↺ Refresh AI Analysis'=>'Odśwież analizę AI ↺','↺ Refreshing…'=>'↺ Odświeżanie…','⚠ Borderline'=>'⚠ Granica','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Nie znaleziono postów <strong>{lang}</strong>. Upewnij się, że wszystkie przetłumaczone posty mają ustawiony meta języka na <strong>{lang}</strong> w metaboxie języka.','⚠ No changes'=>'⚠ Brak zmian','⚠ No changes — re-scan?'=>'⚠ Brak zmian — ponowne skanowanie?','✅ Fixed ({n})'=>'✅ Naprawiono ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Nie znaleziono uszkodzonych linków ani niezgodności szablonów dla <strong>{lang}</strong>. Skanowano <strong>{scanned}</strong> postów i stron — wszystkie kontrole przeszły pomyślnie. Linki do części szablonów (nagłówek, stopka, pasek boczny) nie są tutaj uwzględnione — użyj przycisku Napraw części szablonów, aby sprawdzić je osobno.','✅ Template fixed'=>'✅ Szablon naprawiony','✓ %s notified successfully.'=>'✓ %s pomyślnie powiadomiono.','✓ Active'=>'✓ Aktywne','✓ Active at /lf-sitemap.xml'=>'✓ Aktywne w /lf-sitemap.xml','✓ Active — %d URL entry with language alternates'=>'✓ Aktywne — %d wpisów URL z alternatywami językowymi' . "\0" . '✓ Aktywne — %d wpisów URL z alternatywami językowymi' . "\0" . '','✓ Active — full OG + Twitter Cards'=>'✓ Aktywne — pełne OG + Karty Twittera','✓ Active — locale tags only (og:locale, og:locale:alternate)'=>'✓ Aktywne — tagi lokalizacji tylko (og:locale, og:locale:alternate)','✓ All parts created.'=>'✓ Wszystkie części utworzone.','✓ All templates created.'=>'✓ Wszystkie szablony utworzone.','✓ All translated.'=>'✓ Wszystko przetłumaczone.','✓ Configured'=>'✓ Skonfigurowano','✓ Connection OK'=>'✓ Połączenie OK','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Treść wygenerowana — zobacz nakładkę, aby przejrzeć, dopracować i zastosować.','✓ Done'=>'✓ Zrobione','✓ Enabled'=>'✓ Włączone','✓ Good length'=>'✓ Odpowiednia długość','✓ Hreflang active'=>'✓ Hreflang aktywne','✓ In safe storage'=>'✓ W bezpiecznej pamięci','✓ Language installed.'=>'✓ Język zainstalowany.','✓ LF outputs'=>'✓ Wyniki LF','✓ LF outputs Article / WebPage / WebSite'=>'✓ Wyniki LF artykuł / strona internetowa / witryna','✓ LF outputs full OG + Twitter Cards'=>'✓ Wyniki LF pełne OG + Karty Twittera','✓ LF outputs — plugin hreflang suppressed'=>'✓ Wyniki LF — ukrycie hreflang przez wtyczkę','✓ Links fixed.'=>'✓ Linki naprawione.','✓ Nav refs fixed.'=>'✓ Naprawione odwołania nawigacyjne.','✓ Parts fixed.'=>'✓ Części naprawione.','✓ Pattern translated.'=>'✓ Wzorzec przetłumaczony.','✓ Physical robots.txt found. LF\'s Sitemap directive is present.'=>'✓ Znaleziono fizyczny plik robots.txt. Obecna jest dyrektywa mapy witryny LF.','✓ Refined — review the updated draft above.'=>'✓ Dopracowano — przejrzyj zaktualizowany szkic powyżej.','✓ Translation saved'=>'✓ Tłumaczenie zapisane','✓ WP core canonical removed'=>'✓ Usunięto kanoniczny WP core','✗ %s ping failed. The sitemap URL is still announced in robots.txt — the search engine will discover it on its next crawl.'=>'✗ Nie udało się wysłać ping %s. URL mapy witryny jest nadal ogłaszany w robots.txt — wyszukiwarka odkryje go podczas następnego indeksowania.','✗ Disabled'=>'✗ Wyłączone','✗ Error:'=>'✗ Błąd:','✗ Failed:'=>'✗ Niepowodzenie:','✗ Not configured'=>'✗ Nie skonfigurowano','✗ Too long'=>'✗ Za długo','✗ Too short'=>'✗ Za krótko','❌ Failed'=>'❌ Niepowodzenie','📄 Wrong template'=>'📄 Zły szablon','📍 Stale path (page moved)'=>'📍 Nieaktualna ścieżka (strona przeniesiona)']];
